INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6217', 'spa', 'opresiones, extorsión; actos de injusticia violenta y explotación, o los que sufren tal trato', 'Sustantivo plural que designa actos de opresión o, por extensión, a los oprimidos mismos: quienes padecen explotación e injusticia. Amós denuncia las «opresiones» en los palacios de Samaria (3:9), señalando actos acumulados de violencia. Job pregunta por qué los oprimidos claman bajo sus sufrimientos (35:9). Eclesiastés observa a «los oprimidos» y sus lágrimas, sin consolador alguno (4:1, apareciendo dos veces en el versículo). El término conecta el concepto abstracto (actos opresivos) con la realidad concreta (personas oprimidas), reflejando cómo la injusticia se identifica con sus víctimas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6218', 'spa', 'Una decena, década: el décimo día del mes (ordinal); un instrumento musical de diez cuerdas; el número cardinal diez.', 'Una decena, década: el décimo día del mes (ordinal); un instrumento musical de diez cuerdas; el número cardinal diez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6219', 'spa', 'forjado, trabajado (adjetivo que describe hierro labrado o elaborado con destreza)', 'Ezequiel 27:19 incluye el «hierro forjado» entre los productos de lujo que se comerciaban en Tiro. Este adjetivo describe hierro que ha sido trabajado o forjado con destreza, no mineral en bruto. El texto hebreo presenta cierta dificultad textual, y algunos eruditos proponen raíces o enmiendas alternativas, pero el sentido apunta a metalurgia acabada, apta para el comercio. El término puede derivar de una raíz que significa forjar o trabajar con habilidad. El mercado de Tiro era célebre por su mercancía exótica y de alta calidad, y el hierro forjado habría sido un bien muy valorado en el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6220', 'spa', 'Asvat, nombre propio en la tribu de Aser (1 Crónicas 7:33)', 'Asvat aparece en 1 Crónicas 7:33 dentro de la genealogía de Aser, listado entre los hijos de Jaflet. El nombre solo ocurre aquí y no se conoce nada del individuo más allá de esta referencia genealógica. Las versiones griegas lo transliteran como Aseth o Asouath, con variaciones menores. Las genealogías del Cronista preservan la estructura tribal del norte de Israel, incluida Aser, que se asentó a lo largo de la costa fenicia. Nombres como Asvat anclan a la comunidad postexílica en su pasado ancestral, manteniendo la continuidad con las doce tribus pese a las disrupciones de la conquista y el exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6221', 'spa', 'Asiel, nombre propio en la tribu de Simeón (1 Crónicas 4:35)', 'Asiel se menciona en 1 Crónicas 4:35 dentro de la genealogía de Simeón. Figura entre los antepasados de familias simeonitas, aunque ningún relato acompaña su nombre. El griego transliteran Asiēl, de forma directa. El territorio de Simeón fue absorbido gradualmente por Judá, y muchos simeonitas solo se conocen a través de registros genealógicos como este. La preservación de nombres como Asiel por parte del Cronista refleja la importancia de la identidad tribal y la herencia, incluso para tribus que perdieron su independencia política. Cada nombre representa un linaje con derechos, memorias y un lugar en la comunidad del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6222', 'spa', 'Asaías — ''Yahvé ha hecho''; nombre de un oficial de Josías, un jefe simeonita y varios levitas', 'Asaías es un nombre hebreo teofórico que significa ''Yahvé ha hecho'' o ''YHWH ha actuado''. Su aparición más notable se encuentra en la historia del rey Josías, donde Asaías es uno de los cinco funcionarios enviados a consultar a la profetisa Hulda tras el hallazgo del Libro de la Ley (2 Re 22:12, 14; 2 Cr 34:20). El nombre también pertenece a un líder del clan simeonita que participó en expansiones territoriales (1 Cr 4:36) y a levitas vinculados con la línea merarita y el servicio del Templo (1 Cr 6:30; 9:5; 15:6, 11). Las formas en español como ''Asaías'' y ''Asaya'' reflejan fielmente la vocalización hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6223', 'spa', 'Rico, acaudalado — describe a una persona de abundancia material, frecuentemente contrastada con el pobre o necesitado', 'Rico, acaudalado — describe a una persona de abundancia material, frecuentemente contrastada con el pobre o necesitado');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6224', 'spa', 'Décimo; numeral ordinal que designa posición en una secuencia, o una décima parte fraccionaria usada como medida en prescripciones sacrificiales', 'Décimo; numeral ordinal que designa posición en una secuencia, o una décima parte fraccionaria usada como medida en prescripciones sacrificiales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6225', 'spa', 'Humear, echar humo — de montes ante la presencia teofánica de Dios; figuradamente, arder de ira.', 'Verbo denominativo de עָשָׁן (humo) que describe la emisión de humo, predominantemente en contextos teofánicos. El monte Sinaí ''humeaba'' cuando YHWH descendió en fuego (Ex 19:18), y el salmista celebra que los montes humean al toque de Dios (Sal 104:32; 144:5). La extensión figurada pasa naturalmente del humo visible a la ira invisible: la cólera de YHWH ''humea'' contra los transgresores del pacto (Dt 29:20), y el salmista pregunta por qué la furia de Dios ''humea'' contra las oraciones de su pueblo (Sal 74:1; 80:4). El hebreo mismo tiende un puente entre lo literal y lo metafórico a través de un solo verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6227', 'spa', 'Humo — vapor visible que se eleva del fuego, presencia teofánica, ciudades incendiadas, o como figura de lo transitorio y la ira', 'Humo — vapor visible que se eleva del fuego, presencia teofánica, ciudades incendiadas, o como figura de lo transitorio y la ira');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6228', 'spa', 'Asán; ciudad en la Sefela de Judá, asignada a Simeón y designada como ciudad levítica', 'Nombre de una ciudad que aparece en los repartos territoriales y las listas de ciudades levíticas. Josué 15:42 sitúa a Asán en la Sefela (tierra baja) de Judá, mientras que 19:7 la asigna a Simeón, cuya herencia estaba dentro del territorio de Judá. Primera de Crónicas 4:32 la confirma como asentamiento simeonita y 6:59 la incluye entre las ciudades levíticas. El sitio podría ser idéntico a «Bor-asán» (1 Sam 30:30), donde «Bor» (cisterna o pozo) funciona como prefijo descriptivo. Es un ejemplo típico de asentamiento de la Sefela compartido entre herencias tribales y asignaciones levíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6229', 'spa', 'contender, disputar, enzarzarse en una querella (Hitpael reflexivo/recíproco)', 'Génesis 26:20 relata cómo los pastores de Gerar disputaron con los pastores de Isaac por un pozo, diciendo «el agua es nuestra», e Isaac llamó al pozo Esek, «porque contendieron con él». Este verbo en Hitpael transmite acción recíproca o reflexiva: contender, reñir, enzarzarse en conflicto. La raíz puede estar emparentada con «aferrarse» en la contienda (cf. el árabe «aferrarse con amor», el siríaco «ser difícil, hostil»), o con estar ocupado intensamente, de donde la contienda como compromiso tenaz. En español, «disputaron» capta bien la lucha verbal y quizá física por los derechos de agua en el árido Néguev.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6230', 'spa', 'Eseq, nombre de un pozo que significa ''contienda'' (Génesis 26:20)', 'Eseq es el nombre que Isaac dio a un pozo en Génesis 26:20, después de que los pastores de Gerar disputaran con los suyos reclamando el agua como propia. El nombre significa ''contienda'' o ''disputa'', y conmemora el conflicto por los derechos sobre el agua. La versión griega traduce el nombre como Ἀδικία (''Injusticia''), interpretando el incidente como una apropiación injusta. En Génesis, los nombres de los pozos reflejan las circunstancias de su descubrimiento: Eseq representa la hostilidad, en contraste con Rejobот (''Lugares amplios''), donde Isaac finalmente encuentra paz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6231', 'spa', 'Oprimir, agraviar, extorsionar; como participio: opresor (activo) u oprimido (pasivo) — de עָשַׁק', 'Oprimir, agraviar, extorsionar; como participio: opresor (activo) u oprimido (pasivo) — de עָשַׁק');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6232', 'spa', 'Eseq, nombre propio de un benjaminita de la línea de Saúl (1 Crónicas 8:39)', 'Eseq es un benjaminita mencionado en 1 Crónicas 8:39, incluido entre los descendientes del linaje familiar de Saúl. Su nombre es similar al de Eseq (el pozo de la contienda) y posiblemente comparte la misma raíz, pero aquí funciona como nombre propio. Los manuscritos griegos lo transcriben como Ασηλ o Ασεκ. Fuera de esta nota genealógica, Eseq es completamente desconocido. Las genealogías del Cronista trazan las familias prominentes de Benjamín, incluida la línea real de Saúl, preservando la memoria de individuos cuyas vidas forman parte del registro sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6233', 'spa', 'Opresión o extorsión; la explotación injusta de otros, especialmente de los vulnerables, para beneficio propio', 'El sustantivo ʿōsheq abarca todo el espectro de la injusticia social, desde la explotación sistemática hasta la extorsión individual. Jeremías acusa a Jerusalén porque ''opresión y violencia'' se oyen dentro de sus muros (Jer 6:6), y Ezequiel denuncia a los líderes de Israel por ʿōsheq contra el extranjero, el huérfano y la viuda (Ez 22:7, 29). El salmista ora pidiendo liberación ''de la opresión humana'' (Sal 119:134) y advierte contra confiar en la ganancia de la extorsión (Sal 62:10). Eclesiastés observa que la opresión enloquece al sabio (Ecl 7:7). Isaías promete que la ciudad restaurada no conocerá más ʿōsheq (Is 54:14), y Levítico 6:4 exige restituir lo tomado por extorsión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6234', 'spa', 'opresión, angustia (sustantivo); exclamación ''¡estoy oprimido!'' (Isaías 38:14)', 'Isaías 38:14 registra la oración de Ezequías durante su enfermedad mortal: ''¡Estoy oprimido, sé mi fiador!'' El hebreo dice literalmente ''¡opresión a mí!'', usando este raro sustantivo como exclamación de angustia. La palabra denota el peso aplastante de la aflicción, la sensación de ser aplastado por la enfermedad y la cercanía de la muerte. Algunos eruditos proponen enmendar el texto a ''mi clamor'' (en paralelo con ''voz'' en el verso anterior), pero el texto transmitido dice ''opresión''. En el contexto de una enfermedad terminal, la opresión no proviene de enemigos externos sino de la presión interna y existencial de la mortalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6235', 'spa', 'Diez: número cardinal que aparece en formas masculina y femenina para conteos, edades y medidas.', 'El numeral hebreo diez (עֶשֶׂר/עֲשָׂרָה) impregna la narrativa bíblica en conteos, medidas y estructuras simbólicas. Aparece en edades genealógicas (Gn 5:14), negociaciones (la súplica de Abraham por diez justos en Sodoma, Gn 18:32), los diez mandamientos del Decálogo y unidades organizativas (jefes de diez, Éx 18:21). El sistema hebreo de concordancia de género en los numerales hace que la forma masculina acompañe sustantivos femeninos y viceversa, una inversión gramatical bien conocida. El concepto de ''diez'' no requiere adaptación cultural alguna.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6236', 'spa', 'Diez — numeral cardinal arameo usado en Daniel y Esdras para la bestia de diez cuernos y el número doce.', 'Forma aramea del número cardinal diez, que aparece exclusivamente en las secciones arameas de Daniel y Esdras. En la visión de Daniel, la cuarta bestia tiene diez cuernos que representan diez reyes (Dan 7:7, 20, 24), lo cual convierte a este numeral en pieza central del simbolismo apocalíptico. La forma compuesta ''doce'' (trê ''asar, literalmente ''dos-diez'') aparece en Daniel 4:29 y Esdras 6:17, donde este último registra doce machos cabríos ofrecidos en la rededicación del templo, uno por cada tribu de Israel. La grafía aramea es paralela a su cognado hebreo ''eser.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6237', 'spa', 'Diezmar; en Piel, dar el diezmo como acto de adoración u obligación; en Qal, exigir el diezmo por autoridad real.', 'Verbo denominativo construido sobre la raíz de ''diez'', empleado en dos direcciones contrastantes. En la conjugación Piel describe el acto voluntario y pactal de dar una décima parte a Dios, como cuando Jacob prometió en Betel: ''el diezmo apartaré para ti'' (Gn 28:22), y en las leyes deuteronómicas del diezmo (Dt 14:22; 26:12). En la conjugación Qal, sin embargo, se desplaza hacia el poder del gobernante para exigir una décima parte: Samuel advierte a Israel que el rey ''diezmará vuestro grano y vuestras viñas'' (1 S 8:15, 17). Tanto el español ''diezmar'' como el alemán ''den Zehnten'' conservan la raíz numérica, reflejando el peso universal del concepto de la décima parte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6238', 'spa', 'Enriquecerse o adquirir riqueza; hacer rico o enriquecer a otro; aparentar ser rico.', 'Enriquecerse o adquirir riqueza; hacer rico o enriquecer a otro; aparentar ser rico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6239', 'spa', 'riqueza, riquezas — abundancia material y posesiones, frecuentemente emparejado con honor o contrastado con sabiduría', 'riqueza, riquezas — abundancia material y posesiones, frecuentemente emparejado con honor o contrastado con sabiduría');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6240', 'spa', 'Diez (usado exclusivamente tras dígitos unitarios para formar los compuestos del once al diecinueve, tanto cardinales como ordinales).', 'A diferencia del ''diez'' independiente (H6235 עֶשֶׂר), esta forma aparece únicamente como segundo elemento en los números compuestos del once al diecinueve. Flexiona según el género —עָשָׂר con sustantivos masculinos, עֶשְׂרֵה con femeninos— siguiendo el conocido patrón hebreo de concordancia ''invertida'' en los numerales. Cuando se usa en fórmulas de fecha (el año undécimo, el mes duodécimo), funciona como ordinal sin ningún cambio morfológico, rasgo compartido con el árabe, donde los numerales adolescentes también cumplen doble función. Una anomalía textual en 1 R 22:48 conserva una forma ketiv que los masoretas reapuntaron como derivada de עָשָׂה (H6213, ''hacer'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6241', 'spa', 'décima parte (isarón) — medida de áridos equivalente a un décimo de efa, prescrita para las ofrendas de cereal', 'décima parte (isarón) — medida de áridos equivalente a un décimo de efa, prescrita para las ofrendas de cereal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6242', 'spa', 'Veinte: número cardinal empleado para conteo, edad, medida y numerales compuestos.', 'עֶשְׂרִים es la forma plural indeclinable de diez que funciona como el cardinal ''veinte'' a lo largo de toda la Biblia hebrea. En sus 315 ocurrencias cuenta años de edad (Gn 31:38), codos de medida (Éx 38:18), miles de soldados y fechas del calendario. Se combina libremente con unidades (''veinte mil'', 1 Cr 18:4) y con otros numerales para cantidades compuestas. Es un recordatorio de que los numerales figuran entre los elementos semánticamente más estables de cualquier léxico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6243', 'spa', 'veinte (numeral plural indeclinable en arameo)', 'Daniel 6:1 relata que Darío el medo estableció ''ciento veinte'' sátrapas sobre su reino. Este numeral arameo es la palabra para veinte, y aparece aquí como parte de un número mayor. Los numerales arameos son indeclinables, es decir, no cambian de forma según género o caso. La estructura administrativa descrita —120 sátrapas con tres presidentes sobre ellos, incluido Daniel— prepara el escenario para la conspiración contra Daniel. El número puede ser simbólico (12 x 10, representando totalidad) o histórico. El uso del arameo refleja el contexto: Daniel sirviendo en la corte imperial, donde el arameo era la lengua diplomática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6244', 'spa', 'consumirse, debilitarse, deteriorarse (por aflicción o enfermedad)', 'Este verbo describe el deterioro físico o el consumirse, particularmente por angustia emocional. El salmista lo usa tres veces para expresar cómo el dolor y la angustia han causado estragos físicos. En Salmo 6:7, el ojo ''se consume'' por la tristeza; Salmo 31:9-10 expande esto para incluir alma, vientre y huesos—un declive corporal completo debido a la aflicción. Algunos eruditos proponen derivación de ''polilla'' (como tela apolillada), mientras otros sugieren conexiones con oscuridad o atenuación. El término transmite no una destrucción repentina sino una erosión gradual de vitalidad y fuerza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6245a', 'spa', 'ser liso, brillante, lustroso (posiblemente por gordura; texto incierto)', 'Jeremías 5:28 condena a los malvados: ''Engordaron, están lustrosos'', usando este verbo de significado incierto. La interpretación tradicional es ''liso'' o ''brillante'', describiendo quizás una piel que reluce por el exceso de grasa y el lujo. Sin embargo, la palabra es disputada: algunos proponen enmendar a ''se enriquecieron'', lo cual haría mejor paralelismo con ''engordaron'' (v. 27). El contexto es una denuncia moral: los malvados prosperan materialmente mientras oprimen al pobre, y su apariencia física refleja su autocomplacencia. Ya sea lisos, brillantes o ricos, la imagen retrata una maldad acomodada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6245b', 'spa', 'pensar, considerar, preocuparse (verbo hitpael, aramaísmo; estar atento a, tener en mente)', 'En Jonás 1:6, el capitán del barco suplica a Jonás: «Levántate, invoca a tu dios; quizá él se preocupe por nosotros y no perezcamos.» Este verbo en hitpael es un aramaísmo que significa pensar, considerar o tener presente a alguien. El capitán espera que el Dios de Jonás preste atención a su situación desesperada e intervenga para salvarlos. El verbo es afín al hebreo חָשַׁב (pensar, calcular) y aparece frecuentemente en los Targumes con este mismo sentido. Los marineros paganos, aterrados por la tormenta, confían en que alguna deidad pueda apiadarse si se le invoca con fervor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6246', 'spa', 'pensar, planear, proponerse (verbo arameo; participio pasivo en Daniel 6:4)', 'Daniel 6:4 relata que «el rey pensaba poner a Daniel sobre todo el reino», usando este verbo arameo. La forma es estrictamente un participio pasivo, «fue pensado» o «fue planeado», pero funciona como un tiempo perfecto finito. El verbo significa pensar o planear, con cognados en el hebreo bíblico y en los Targumes, aunque no se encuentra en siríaco. La intención favorable de Darío hacia Daniel desata la conspiración de los funcionarios celosos que buscan destruirlo. El arameo refleja el lenguaje de la corte imperial, donde Daniel navega la peligrosa política del alto gobierno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6247', 'spa', 'placa, lámina (objeto liso y brillante; posiblemente incrustación de marfil o metal)', 'Cantares 5:14 describe el cuerpo del amado: «Su vientre es una placa de marfil, cubierta de zafiros.» Este sustantivo poco frecuente designa una placa o lámina, una superficie lisa y pulida. La imagen evoca marfil bruñido, quizá incrustado con piedras azules, sugiriendo tanto belleza como lujo. La palabra puede derivar de una raíz que significa «liso» o «brillante», usada en otros contextos para metales refinados. La metáfora compara el cuerpo del amado con materiales preciosos: marfil por su blancura y suavidad, zafiros por su resplandor. El lenguaje del Cantar es exuberante, acumulando imágenes de riqueza para expresar la admiración entre los amantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6248', 'spa', 'pensamiento, forma de pensar (sustantivo constructo en Job 12:5)', 'Job 12:5 es un versículo notoriamente difícil: «Para el pensamiento del que vive tranquilo, la desgracia merece desprecio.» Este sustantivo poco frecuente denota pensamiento o actitud mental, usado aquí en estado constructo. El versículo critica a quienes viven cómodamente y desprecian el sufrimiento ajeno, asumiendo que la desgracia es merecida. La palabra se relaciona con una raíz que significa «pensar». El punto central es la mentalidad complaciente de los prósperos, que en su autosatisfacción solo sienten desdén por el infortunio, suponiendo que jamás les tocará. Job lo sabe bien, habiendo caído de la prosperidad a la ruina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6249', 'spa', 'Once, undécimo: el número once en usos cardinales y ordinales, siempre en constructo con diez (עָשָׂר/עֶשְׂרֵה).', 'Once, undécimo: el número once en usos cardinales y ordinales, siempre en constructo con diez (עָשָׂר/עֶשְׂרֵה).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6250', 'spa', 'pensamiento, plan, propósito (especialmente los que perecen con la muerte)', 'Este raro sustantivo hebreo aparece únicamente en el Salmo 146:4, donde describe los pensamientos o planes del mortal que se desvanecen cuando el aliento lo abandona. La palabra transmite un sentido de fragilidad: los proyectos y propósitos mentales que parecen tan importantes en vida desaparecen con la muerte. El salmista contrasta la transitoriedad de los planes humanos con la fidelidad eterna de Dios. La evidencia multilingüe (español «pensamientos», francés «pensée», alemán «Pläne») interpreta este término consistentemente como actividad cognitiva o planificación que resulta efímera al cesar la vida humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6251', 'spa', 'crías del rebaño, prole; el incremento y la fertilidad de las ovejas, posiblemente ovejas o corderos', 'Término que aparece exclusivamente en las fórmulas de bendición y maldición del Deuteronomio, designando el incremento fértil del rebaño. La expresión «las crías de tu rebaño» se empareja con «la cría de tu ganado», representando la fertilidad del ganado como bendición del pacto o su ausencia como maldición. Los estudiosos debaten si se refiere específicamente a ovejas hembras, corderos jóvenes o al éxito reproductivo general del rebaño. La posible conexión con Astarté (diosa de la fertilidad) sugiere que el término enfatiza la fecundidad y la multiplicación. Deuteronomio lo emplea para condensar la prosperidad pastoral: rebaños que se multiplican abundantemente bajo la bendición de Dios, o que decaen bajo su maldición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6252', 'spa', 'Astarot: ciudad en Basán al este del Jordán; también nombre plural de las diosas/ídolos cananeos de Astarté', 'Esta palabra abarca dos referentes distintos que comparten una raíz común en el culto a la diosa Astart. Como topónimo, Astarot designa una ciudad importante de Basán, sede real de Og (Dt 1:4; Jos 12:4), asignada posteriormente a los levitas. Como plural divino, se refiere a las diosas Astarté o a sus imágenes de culto, contraparte femenina de los Baales en la religión cananea. El libro de Jueces registra reiteradamente que Israel ''sirvió a las Astarot'' (Jue 2:13; 10:6). En español se distinguen con claridad: la ciudad se nombra simplemente Astarot, mientras que los ídolos reciben el artículo ''las Astarot'', identificándolos como una clase de divinidades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6253', 'spa', 'Astarot, diosa cananea/fenicia del amor y la guerra', 'Astarot (también Astarté) era una diosa cananea y fenicia importante de la fertilidad, el amor y la guerra, correspondiente a la Ishtar mesopotámica y la Afrodita griega. El nombre aparece en hebreo con vocales tomadas de ''boshet'' (vergüenza), reflejando el desdén de los escribas israelitas hacia la deidad. Salomón infamemente construyó un lugar alto para Astarot cuando fue influenciado por sus esposas extranjeras (1 Reyes 11:5, 33), y este santuario permaneció hasta que las reformas de Josías lo destruyeron (2 Reyes 23:13). El culto a la diosa involucraba prostitución ritual y representaba todo lo opuesto al culto exclusivo de Yahveh. Su culto estaba muy extendido por todo el antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6254', 'spa', 'el asteratita (gentilicio que indica procedencia de Astarot)', 'Adjetivo gentilicio hebreo que identifica a alguien originario de Astarot, una ciudad en Basán al este del Jordán. En 1 Crónicas 11:44, este término designa a uno de los guerreros valientes de David por su lugar de origen. Como muchos de estos gentilicios en las genealogías y listas militares bíblicas, proporcionaba identidad geográfica y tribal dentro de la estructura social del antiguo Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6255', 'spa', 'en Astarot-Carnaim (topónimo al este del Jordán)', 'Topónimo compuesto que aparece en Génesis 14:5 durante el relato de la campaña de los reyes orientales. El nombre combina Astarot (vinculado al culto de la diosa Astarté) con Carnaim («dos cuernos»), posiblemente en referencia a un monte de doble cima o a un símbolo cultual. El sitio se ubicaba en Basán, al este del mar de Galilea, y podría corresponder a Tell Ashtara o Muzeirib en la actual Jordania.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6256', 'spa', 'Tiempo, estación o momento señalado: punto o período temporal, desde referencia general hasta ocasión divinamente dispuesta.', 'Uno de los sustantivos temporales más frecuentes de la Biblia hebrea, con cerca de 300 ocurrencias. Lejos de ser una palabra neutra de reloj, עֵת porta una rica carga teológica: es el tiempo que Dios fija (Lv 26:4, ''daré vuestras lluvias a su tiempo''), el momento de crisis que sobreviene (Jer 8:7, ''la cigüeña conoce sus tiempos señalados'') y el marcador narrativo que ancla los acontecimientos (''en aquel tiempo''). El uso hebreo se divide entre la referencia temporal neutra y el sentido pregnante de kairós —el tiempo justo, el momento oportuno—, distinción que se hace visible cuando las traducciones añaden calificativos como ''en su sazón'' o ''por este tiempo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6258', 'spa', 'Ahora — adverbio temporal que marca el momento presente, frecuente en la fórmula ''y ahora'' o en ''desde ahora''.', 'עַתָּה es el adverbio principal de la Biblia hebrea para señalar el momento presente, con más de 430 apariciones. Su uso más característico es la fórmula de transición וְעַתָּה (''y ahora''), que articula el paso de una narración o situación pasada hacia una implicación, mandato o conclusión presente: ''Y ahora, he aquí tu mujer'' (Gn 12:19), ''¿Y ahora, Israel, qué pide de ti el SEÑOR tu Dios?'' (Dt 10:12). Un patrón menor pero teológicamente significativo es מֵעַתָּה (''desde ahora''), que expresa duración desde el presente hacia un futuro indefinido, como en el doxológico ''desde ahora y para siempre'' (Sal 113:2; 115:18; 121:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6260', 'spa', 'Macho cabrío; cabra macho adulta usada en sacrificios y como ganado; figuradamente, un líder o jefe entre el pueblo.', 'Macho cabrío; cabra macho adulta usada en sacrificios y como ganado; figuradamente, un líder o jefe entre el pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6261', 'spa', 'dispuesto, preparado o designado (quien está listo para una tarea específica)', 'Este adjetivo hebreo describe a alguien en estado de preparación o designación para una tarea concreta. En Levítico 16:21, designa al hombre preparado para conducir al macho cabrío expiatorio al desierto durante el Día de la Expiación, alguien específicamente escogido y dispuesto para este acto ritual. El término implica tanto oportunidad temporal como preparación práctica, sugiriendo a alguien debidamente posicionado y equipado para actuar de inmediato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6262', 'spa', 'Atai; nombre propio de significado incierto, llevado por hombres de Judá, Gad y la casa de David', 'Nombre propio que aparece en genealogías y listas militares. Primera de Crónicas 2:35-36 registra a Atai en la genealogía de Judá como hijo de un esclavo egipcio y nieto de Sesán. Otro Atai figura entre los guerreros gaditas que se unieron a David (12:11). Un tercer Atai se menciona como hijo de Roboam (2 Cr 11:20). Las transliteraciones de la LXX varían (Ietthei), algo habitual en los nombres propios. La etimología del nombre es incierta, posiblemente relacionada con una raíz que significa «oportuno» o «dispuesto». Estas entradas genealógicas documentan líneas familiares y registros militares sin desarrollo narrativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6263', 'spa', 'preparados, dispuestos (adjetivo arameo en plural)', 'Este adjetivo arameo aparece en Daniel 3:15 durante el desafío de Nabucodonosor a Sadrac, Mesac y Abednego. El rey les pregunta si están «preparados» para postrarse ante la imagen de oro al escuchar la música. La palabra transmite el sentido de estar dispuesto o listo para ejecutar una acción, de forma similar a su cognado hebreo. Aparece en la porción aramea de Daniel, reflejando el contexto lingüístico de la corte babilónica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6264', 'spa', 'Listo, preparado, dispuesto para la acción; tesoros o provisiones (variante ketiv)', 'El adjetivo עָתִיד describe un estado de preparación o disposición: alguien o algo a punto de actuar de manera inminente. El rey malvado de Job está ''listo para el combate'' (Job 15:24), el decreto real hace que los ciudadanos estén ''preparados para aquel día'' (Est 3:14; 8:13), y los expertos en despertar al Leviatán son descritos como practicantes ''listos'' (Job 3:8). El cántico de Moisés advierte que ''las cosas preparadas se apresuran'' (Deut 32:35), con matiz de destino inminente. Una variante ketiv en Isa 10:13 lee la forma como sustantivo que significa ''tesoros'' o ''riqueza almacenada''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6265', 'spa', 'Ataías (nombre propio que posiblemente significa «Yahvé ha ayudado»)', 'Nombre propio que aparece en Nehemías 11:4, identificando a un descendiente de Judá que se reasentó en Jerusalén tras el exilio babilónico. El nombre presenta problemas textuales, con variantes en los pasajes paralelos y las versiones antiguas. La Septuaginta ofrece «Athea», mientras que 1 Crónicas 9:4 presenta la forma paralela «Utai». Esta clase de variación era frecuente en la transmisión de listas genealógicas bíblicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6266', 'spa', 'selecto, excelente, eminente o valioso (que describe una cualidad superior)', 'Adjetivo hebreo que describe algo de calidad superior o eminencia. En Isaías 23:18 se usa para caracterizar ''vestidura selecta'' o ''ropa distinguida'', es decir, prendas de calidad excepcional. La palabra transmite la idea de algo que sobresale o supera lo ordinario, ya sea por su valor material, su manufactura o su excelencia. Relacionado con la noción de que la antigüedad confiere valor, enfatiza distinción y superioridad sobre lo común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6268', 'spa', 'Anciano de Días, el de edad avanzada', 'Este adjetivo arameo significa ''avanzado'' o ''anciano,'' apareciendo exclusivamente en la visión apocalíptica de Daniel como el título ''Anciano de Días.'' La frase describe la figura eterna y soberana sentada en un trono de fuego, de quien el Hijo del Hombre recibe dominio. La imaginería enfatiza existencia atemporal, sabiduría y autoridad suprema—uno que precede toda la creación y preside sobre el juicio cósmico. Daniel 7 usa este título tres veces cuando el juez divino toma su asiento, recibe adoración y ejecuta justicia. El término se volvió influyente en representaciones teológicas y artísticas de la naturaleza eterna de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6269', 'spa', 'Atac (nombre de un lugar en Judá)', 'Nombre de un lugar mencionado en 1 Samuel 30:30, donde David envió porciones del botín recuperado de los amalecitas. Situado en el territorio de Judá, Atac fue una de las ciudades que recibieron regalos de David, fortaleciendo así sus relaciones con las comunidades de Judá antes de convertirse en rey. El sitio no ha sido identificado con certeza, y algunos estudiosos han propuesto enmiendas textuales, pero el nombre se mantiene en el texto recibido como una de las ciudades aliadas de David en el sur.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6270', 'spa', 'Atlai (nombre personal masculino que posiblemente significa ''Yahvé es exaltado'')', 'Nombre personal que aparece en Esdras 10:28, identificando a uno de los israelitas que se habían casado con mujeres extranjeras durante el exilio y a quienes se les exigió divorciarse como parte de las reformas de Esdras. El nombre figura en la lista de quienes habían violado la prohibición contra los matrimonios mixtos. Distinto del nombre femenino más conocido Atalía, esta forma masculina aparece únicamente en este contexto postexílico de restauración religiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6271', 'spa', 'Atalía — reina madre de Judá que usurpó el trono durante seis años; también nombre de dos hombres del período postexílico. Principalmente el nombre de', 'Atalía — reina madre de Judá que usurpó el trono durante seis años; también nombre de dos hombres del período postexílico. Principalmente el nombre de la célebre reina madre que se apoderó del trono de Judá tras la muerte de su hijo Ocozías a manos de Jehú. Hija (o nieta) de Omrí y Acab, introdujo el culto a Baal en el reino del sur e intentó exterminar la línea davídica; solo el infante Joás sobrevivió, oculto en el templo durante seis años (2 Re 11:1-3). Su dramático derrocamiento por el sacerdote Joiada (2 Re 11:13-20) restauró tanto la monarquía davídica como el culto a Yahvé. El nombre también aparece para un benjaminita (1 Cr 8:26) y dos figuras postexílicas (Esd 8:7; 10:28). La forma griega Gotalía conserva el nombre en la tradición de la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6272', 'spa', 'ser abrasado, oscurecido u ofuscado (verbo dudoso de significado incierto)', 'Verbo hebreo raro y disputado que aparece en Isaías 9:19 (TM 9:18), donde el Texto Masorético dice que ''la tierra fue abrasada'' u ''oscurecida''. El significado de la raíz es incierto: los cognados árabes sugieren ya sea calor abrasador o estar obstruido u oscurecido. Muchos estudiosos sospechan corrupción textual y proponen leer un verbo diferente, quizás de la raíz que significa ''arder''. El contexto describe la naturaleza consumidora de la ira de Dios, con imágenes de fuego y tinieblas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6273', 'spa', 'Otni (nombre personal levítico)', 'Nombre levítico que aparece en 1 Crónicas 26:7, identificando a uno de los porteros asignados al servicio del templo en la organización que David hizo de las funciones levíticas. El nombre forma parte de los registros genealógicos que documentan a las familias e individuos responsables de custodiar las entradas del santuario. Como muchos nombres levíticos en Crónicas, preserva la memoria de quienes sirvieron en la infraestructura del culto de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6274', 'spa', 'Otoniel; nombre propio del primer juez de Israel, hijo de Cenaz y hermano menor de Caleb', 'El nombre personal Otoniel (עָתְנִיאֵל), que posiblemente significa ''león de Dios'' o ''Dios es mi fortaleza''. Es el primer juez levantado por el Señor para librar a Israel después de la generación de Josué (Jue 3:9-11). Hijo de Cenaz y hermano menor de Caleb, aparece por primera vez conquistando Quiriat-séfer y ganando como esposa a Acsa, hija de Caleb (Jos 15:17; Jue 1:13). El Cronista registra a sus descendientes (1 Cr 4:13) y el servicio militar de su familia (1 Cr 27:15). La transliteración al español como Otoniel es consistente con la forma hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6275', 'spa', 'Moverse, avanzar, proceder; envejecer; ser desplazado; remover; transcribir — raíz versátil que abarca movimiento, envejecimiento y copia textual.', 'Verbo hebreo notablemente flexible cuyos sentidos van desde la reubicación física hasta el paso del tiempo mismo. Cuando Abraham ''se trasladó'' de allí hacia Betel (Gn 12:8), fue este verbo el que describió su viaje. Sin embargo, la misma raíz puede describir ojos que se debilitan por el dolor (Sal 6:7) o una roca inamovible que es desplazada de su lugar (Job 14:18). Su uso más sorprendente aparece en Pr 25:1, donde los escribas de Ezequías ''copiaron'' los proverbios de Salomón — un sentido que probablemente se desarrolló a partir de la idea de transferir o mover texto de un rollo a otro. El cognado árabe ataqa (''envejecer, quedar libre'') y el arameo athiq (''ser antiguo'') iluminan los sentidos de envejecimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6276', 'spa', 'perdurable, valioso, antiguo o sobresaliente (describe riqueza duradera o excelencia probada por el tiempo)', 'Adjetivo hebreo que describe algo perdurable, valioso o sobresaliente por su antigüedad o excelencia intrínseca. En Proverbios 8:18, califica la «riqueza duradera» que ofrece la Sabiduría: bienes que permanecen, en contraste con la ganancia material pasajera. El término vincula la antigüedad con el valor, sugiriendo que la verdadera excelencia se demuestra con el paso del tiempo. Los cognados árabes refuerzan la idea de algo que precede y que, por tanto, resulta superior o escogido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6277', 'spa', 'arrogancia, insolencia; discurso o actitud arrogante marcados por presunción y soberbia', 'Adjetivo que describe un discurso o actitud arrogante e insolente. La oración de Ana advierte contra dejar que la arrogancia brote de la boca (1 Sam 2:3), equiparándola con la jactancia soberbia contra Dios. Los Salmos condenan el habla insolente: las palabras arrogantes de los impíos (31:18), la altivez presuntuosa (75:5) y las declaraciones jactanciosas de los malvados (94:4). El término capta un habla que excede los límites apropiados: declaraciones presuntuosas y desenfrenadas que exaltan al ser humano por encima de Dios y del prójimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6278', 'spa', 'Itá-Casín (topónimo en la frontera de Zabulón)', 'Nombre de lugar compuesto que aparece únicamente en Josué 19:13, señalando un punto en el límite del territorio tribal de Zabulón. El nombre incluye una terminación locativa direccional. Su ubicación exacta se desconoce, ya que solo se menciona en esta descripción de fronteras sin indicios geográficos suficientes para una identificación moderna. Estos mojones territoriales eran cruciales en el reparto de tierras tribales, pero muchos sitios se han perdido en la historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6279', 'spa', 'Orar, suplicar o rogar a Dios (Qal/Hifil); ser suplicado y conceder la oración (Nifal, referido a Dios). El verbo עָתַר pertenece al vocabulario íntim', 'Orar, suplicar o rogar a Dios (Qal/Hifil); ser suplicado y conceder la oración (Nifal, referido a Dios). El verbo עָתַר pertenece al vocabulario íntimo de la oración bíblica, describiendo tanto el acto humano de súplica como la respuesta graciosa de Dios. Su cognado árabe ʿatara (''sacrificar'') sugiere raíces rituales: la súplica como algo ofrecido, costoso y fervoroso. En el Nifal, el sujeto siempre es Dios: Él ''fue suplicado'' por Isaac y Rebeca (Gn 25:21), por la tierra tras la crisis gabaonita (2 S 21:14), e incluso por el malvado Manasés que se arrepintió en el exilio (2 Cr 33:13). Las formas Hifil y Qal capturan el lado humano: Moisés rogando a Dios que retire las plagas de Egipto (Éx 8:28-30, 9:28, 10:18), y Manoa orando por orientación sobre el hijo prometido (Jue 13:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6282a', 'spa', 'adoradores, suplicantes (los que oran o hacen súplica a Dios)', 'Sustantivo hebreo poco frecuente que aparece solo en Sofonías 3:10, donde designa a los adoradores o suplicantes dispersos de Dios. El término describe a quienes oran u ofrecen súplica, y en el contexto de Sofonías se refiere a los israelitas dispersos que traerán ofrendas desde más allá de los ríos de Cus. Su significado es algo incierto: algunos lo entienden como «suplicantes» y otros como «adoradores». Ambas acepciones captan la idea de personas que se acercan con devoción a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6282b', 'spa', 'olor, fragancia (específicamente del incienso en contexto ritual)', 'Sustantivo hebreo que designa el olor o la fragancia, particularmente en contextos rituales. Ezequiel 8:11 lo emplea para describir la nube aromática de incienso que se elevaba durante un acto de adoración idolátrica. El término es textualmente incierto (BDB lo marca como «si vera lectio») y podría tratarse de un préstamo arameo. En su contexto, capta la dimensión sensorial del culto: la densa nube de humo de incienso que acompañaba la idolatría secreta de los ancianos en el templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6283', 'spa', 'abundancia, plenitud (especialmente de paz o prosperidad)', 'Sustantivo hebreo poco frecuente que aparece en Jeremías 33:6, donde Dios promete revelar «abundancia de paz» a la Judá restaurada. Se trata de un aramaísmo (palabra tomada del arameo), aunque su lectura es discutida en algunos testimonios textuales. Transmite la idea de prosperidad abundante, plenitud o paz desbordante. El contexto habla de sanación y restauración, y este término subraya el carácter generoso y copioso de la restauración divina que ha de venir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6284', 'spa', 'dispersar, esparcir o partir en pedazos (verbo de significado incierto)', 'Un verbo hebreo disputado que aparece en Deuteronomio 32:26, dentro del cántico de juicio de Moisés. La forma Hifil del Texto Masorético sugiere el sentido de «los dispersaré» o posiblemente «los partiré en pedazos». El significado exacto es incierto; la Septuaginta parece leer un verbo diferente con el sentido de dispersar. Cognados árabes apuntan a «hender» o «dividir». El contexto describe el juicio divino contra la rebelión de Israel, con la imagen de dispersar al pueblo tan completamente que su memoria se borraría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6285', 'spa', 'Esquina, lado o borde; porción limítrofe de una estructura, territorio o cuerpo, incluidas las sienes de la cabeza.', 'Esquina, lado o borde; porción limítrofe de una estructura, territorio o cuerpo, incluidas las sienes de la cabeza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6286a', 'spa', 'Embellecer, glorificar o adornar (Piel); glorificarse a sí mismo o jactarse (Hitpael)', 'Un verbo de rica carga teológica que abarca desde el embellecimiento físico hasta la autoglorificación divina. En el Piel, Dios embellece su templo (Isa 60:13) y adorna a los humildes con salvación (Sal 149:4). En el Hitpael, el sentido reflexivo se bifurca: positivamente, Dios se glorifica a sí mismo en Israel (Isa 44:23; 49:3); negativamente, los seres humanos se jactan o se vanaglorian (Jue 7:2; Isa 10:15). El español distingue bien entre ''hermosear'' (embellecer) y ''gloriarse'' (jactarse), captando ambos polos semánticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6286b', 'spa', 'rebuscar las ramas, espigar (verbo denominativo derivado de ''rama'')', 'Un raro verbo Piel que aparece en Deuteronomio 24:20, donde se instruye a los israelitas a no rebuscar las ramas del olivo tras la cosecha, es decir, a no despojar los árboles por completo recogiendo una segunda vez. Esta ley protegía a los pobres y extranjeros al exigir que los propietarios dejaran parte del fruto para ellos. El verbo es denominativo, derivado de un sustantivo que significa «rama», y literalmente designa la acción de repasar las ramas para recoger los frutos restantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6287', 'spa', 'tocado, turbante, ornamento para la cabeza; usado por sacerdotes, novios y como señal de gozo', 'Sustantivo que designa un ornamento para la cabeza: turbante, tocado o guirnalda festiva según el contexto. En la legislación sacerdotal describe los turbantes de lino de los sacerdotes (Éx 39:28; Ez 44:18). Isaías transforma la imagen: Dios otorga una ''corona de hermosura'' en lugar de ceniza a los que lloran (Is 61:3), y el novio se adorna como un sacerdote con su turbante (Is 61:10). Ezequiel emplea la misma palabra para el turbante cotidiano que los dolientes no deben quitarse (Ez 24:17, 23). Las traducciones españolas como tocado y turbante confirman la cualidad ornamental y dignificante de esta prenda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6288a', 'spa', 'ramaje, ramas; las ramas extendidas de un gran arbol, usadas figuradamente para imperios', 'Sustantivo femenino empleado exclusivamente en las grandes alegorias arboreas de Ezequiel, donde cedros y vides majestuosos simbolizan imperios y reinos. En Ez 17:6 describe las ramas extendidas de una vid que representa la casa real de Juda. La extensa alegoria del cedro en Ezequiel 31 lo emplea repetidamente: las ramas del gran arbol crecieron largas (31:5), las aves anidaban en ellas (31:6), ningun arbol podia rivalizar con ellas (31:8), y cuando el arbol cae, su ramaje queda quebrado por montes y valles (31:12-13). El espanol ''ramas'' y ''ramaje'' capturan la imagen de frondosas extremidades arboreas que simbolizan el alcance y poder politico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6288b', 'spa', 'copa, ramaje, ramas altas (sustantivo colectivo para las ramas de un árbol)', 'Un sustantivo colectivo hebreo que designa la copa o el ramaje de un árbol, presente en Isaías 10:33. El texto describe a Dios podando las ramas altas del orgullo asirio con poder aterrador. La palabra presenta variantes textuales (Ketiv פארה frente a Qere פורה), lo cual refleja cierta incertidumbre escribal sobre la forma exacta. Aparece en una vívida metáfora que compara a los orgullosos líderes de Asiria con un bosque que Dios talará, despojándolo de sus ramas más elevadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6290', 'spa', 'Parán, región desértica al noreste del Sinaí asociada con las peregrinaciones de Israel por el desierto', 'Una vasta extensión desértica que se extiende entre el Sinaí y el Néguev, Parán aparece en momentos decisivos del itinerario de Israel. Agar e Ismael se establecen en su desierto (Gn 21:21), e Israel acampa allí tras partir del Sinaí (Nm 10:12). Es desde el desierto de Parán que se envían los doce espías a explorar Canaán (Nm 13:3), convirtiéndolo en el punto de partida de una de las decisiones más trascendentales de las Escrituras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6291', 'spa', 'brevas, higos tempranos (higos en su primera etapa verde, antes de madurar)', 'Un sustantivo hebreo que designa los higos tempranos o brevas—frutos en su primera etapa verde, antes de la maduración completa. Cantar de los Cantares 2:13 menciona «sus brevas» como señal de la primavera, parte del despertar natural que invita a la amada a levantarse. Estos higos tempranos, que aparecen en el árbol antes de la cosecha principal, eran valorados como heraldos de la temporada fructífera y símbolos de nueva vida y fertilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6292', 'spa', 'cosa inmunda, carne contaminada; carne sacrificial que se ha vuelto ritualmente impura e inaceptable', 'Término técnico para la carne sacrificial que se ha vuelto ritualmente inmunda y abominable, quedando no apta para el consumo ni la ofrenda. Levítico establece que si alguien come carne sacrificial al tercer día, esta se convierte en cosa inmunda y la ofrenda queda invalidada (7:18, 19:7). Isaías lo emplea para el caldo de cosas abominables consumido en rituales paganos (65:4). El horror de Ezequiel ante comer carne inmunda (4:14) expresa su preocupación por la contaminación ritual. El término denota no simplemente impureza, sino algo abominable: religiosamente repugnante y profanador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6293', 'spa', 'Encontrar, golpear, alcanzar; abarca desde el encuentro fortuito hasta el asalto violento, la intercesión y el alcance de un límite geográfico', 'Encontrar, golpear, alcanzar; abarca desde el encuentro fortuito hasta el asalto violento, la intercesión y el alcance de un límite geográfico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6295', 'spa', 'Pagiel, hijo de Ocrán; jefe designado de la tribu de Aser durante el período del desierto', 'Nombre propio que significa ''encuentro de Dios'' o ''Dios ha salido al encuentro'', llevado por el líder designado de la tribu de Aser durante las peregrinaciones por el desierto. Pagiel hijo de Ocrán aparece en el censo (Nm 1:13), la disposición del campamento tribal (Nm 2:27), las ofrendas de dedicación del tabernáculo (Nm 7:72, 77) y el orden de marcha (Nm 10:26). El francés ''Paguiel'' conserva una vocalización ligeramente distinta, mientras que el español, el inglés y el alemán coinciden en la forma ''Pagiel''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6297', 'spa', 'Cadáver, cuerpo sin vida; un cuerpo muerto, ya sea humano o animal, frecuentemente de los caídos o los que están bajo juicio divino.', 'Cadáver, cuerpo sin vida; un cuerpo muerto, ya sea humano o animal, frecuentemente de los caídos o los que están bajo juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6298', 'spa', 'Encontrar o encontrarse con alguien; reunirse mutuamente; toparse con alguien de manera fortuita', 'Un verbo hebreo sinónimo del más frecuente פָּגַע, pero con su propio matiz de encuentro cara a cara. Cuando Jacob prepara a sus siervos para ''cuando Esaú te encuentre'' (Gn 32:17), o cuando Abigail sale al encuentro de David (1 Sam 25:20), este verbo capta el momento de intersección entre dos partes en movimiento. La forma Nifal recíproca produce una de las imágenes más bellas de la Escritura: ''La misericordia y la verdad se encontraron'' (Sal 85:10). Proverbios observa que ricos y pobres ''se encuentran'' — el SEÑOR los hizo a ambos (Pr 22:2; 29:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6299', 'spa', 'Rescatar o redimir pagando un precio; librar de la esclavitud, la muerte o el peligro; (Nifal) ser redimido; (participio) redentor, los redimidos', 'Rescatar o redimir pagando un precio; librar de la esclavitud, la muerte o el peligro; (Nifal) ser redimido; (participio) redentor, los redimidos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6300', 'spa', 'Pedahel (nombre propio que significa ''Dios ha rescatado'')', 'Un nombre propio que significa «Dios ha rescatado» o «El ha redimido», presente en Números 34:28. Pedahel fue el príncipe o líder de la tribu de Neftalí, designado para ayudar a repartir la Tierra Prometida entre las tribus. El nombre refleja los patrones teofóricos comunes en Israel, combinando el nombre divino El con un verbo que expresa redención. Nombres similares en fenicio y asirio muestran que este era un patrón onomástico semítico ampliamente difundido que celebraba la liberación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6301', 'spa', 'Pedahzur — ''la Roca ha redimido''; padre de Gamaliel, líder de Manasés en el desierto', 'Nombre teofórico que combina pedah (''rescate'') y tsur (''roca''), expresando la confesión de que Dios — la Roca de Israel — ha redimido. Pedahzur aparece exclusivamente en Números como padre de Gamaliel, el jefe designado sobre la tribu de Manasés durante el censo y la marcha por el desierto (Num 1:10, 2:20, 7:54, 59, 10:23). El nombre encaja en un patrón de nombres con temática de redención entre los líderes tribales, afirmando la liberación divina en el momento mismo en que Israel se organizaba como comunidad del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6302', 'spa', 'los redimidos, precio de rescate; aquellos redimidos mediante pago, o el precio de la redención misma', 'Término que designa a los redimidos o el pago de redención, apareciendo únicamente en Números 3 en el contexto de la sustitución levítica. Dado que los primogénitos israelitas (22.273) superaban en número a los levitas (22.000), los 273 excedentes requerían redención mediante pago. El precio de redención (cinco siclos por persona) fue recaudado y entregado a Aarón y sus hijos. Las variantes textuales y la gramática incierta sugieren que el término abarca tanto a las personas redimidas como al pago de rescate. El contexto enfatiza la transacción: primogénitos excedentes liberados mediante sustitución monetaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6304', 'spa', 'redención, rescate; liberación obtenida mediante pago o acción divina de salvación', 'Sustantivo abstracto que designa la redención o el rescate: liberación lograda mediante pago o intervención divina. Éxodo 8:23 lo emplea para la distinción (o redención) que Dios establece entre Israel y Egipto durante las plagas, aunque el texto y su significado son inciertos. El Salmo 111:9 celebra la redención que Dios envió a su pueblo, la liberación del Éxodo. El Salmo 130:7 asegura que en el Señor hay redención abundante del pecado, animando a la esperanza en el perdón divino. Isaías 50:2 cuestiona si la mano de Dios es demasiado corta para redimir del exilio. El término abarca tanto la redención transaccional como la redención relacional de los actos salvíficos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6305', 'spa', 'Pedaías / Pedayahu — ''YHWH ha rescatado''; nombre compartido por varias figuras bíblicas del período monárquico al postexílico', 'Pedaías es un nombre teofórico que significa ''YHWH ha rescatado'', combinando la raíz פדה (redimir, rescatar) con el nombre divino. Aparece a lo largo de un período sorprendentemente amplio. Un Pedaías es mencionado como abuelo materno del rey Joacim (2 Re 23:36), y un hijo de Jeconías con ese nombre aparece en la genealogía real postexílica como padre de Zorobabel según Crónicas (1 Cr 3:18-19). Otros portadores incluyen un oficial manasita bajo David (1 Cr 27:20), un constructor del muro bajo Nehemías (Neh 3:25), un benjamita (Neh 11:7) y un levita tesorero (Neh 13:13). La forma larga Pedayahu aparece únicamente para el líder manasita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6306a', 'spa', 'redención, rescate (el precio pagado para redimir a los primogénitos excedentes)', 'Sustantivo hebreo poco frecuente que aparece en Números 3:49, donde se refiere al dinero de rescate o precio de redención. El término designa la cantidad recaudada por Moisés para los 273 primogénitos israelitas que excedían el número de levitas disponibles como sustitutos. Este pago liberaba al primogénito de su consagración a Dios, obligación establecida tras el éxodo. El texto es problemático: muchos eruditos prefieren leer el participio pasivo (''los redimidos'') en lugar del sustantivo (''la redención''), como sugiere la lectura Qeré del versículo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6307', 'spa', 'Padán-Aram, la llanura de la alta Mesopotamia en torno a Harán, tierra de origen de la familia patriarcal', 'Este topónimo compuesto designa la llanura fértil que rodea Harán en la alta Mesopotamia, patria ancestral de la familia extendida de Abraham. De allí procede Rebeca, esposa de Isaac (Gn 25:20), y allí es enviado Jacob para buscar esposa entre los parientes de su madre (Gn 28:2). El nombre evoca la práctica patriarcal de buscar matrimonios dentro de la familia del pacto, vinculando las promesas de Canaán con las raíces mesopotámicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6308', 'spa', 'redímelo (forma verbal imperativa con sufijo pronominal que expresa liberación divina)', 'Forma verbal que aparece en Job 33:24, donde Elihú describe cómo Dios muestra favor a una persona que sufre. El texto dice ''redímelo'' o ''líbralo'', expresando el mandato divino de rescatar al sufriente del descenso a la fosa. La forma combina un imperativo con un sufijo pronominal, comunicando la misericordia de Dios que libra de la muerte. El versículo es textualmente complejo: algunos lo interpretan como una forma abreviada del topónimo Padán-Aram, aunque la lectura verbal se ajusta mejor al contexto de intervención divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6309', 'spa', 'sebo, grasa interior (grasa animal interna usada en sacrificios)', 'Este término se refiere a la grasa interior de los animales sacrificiales, particularmente la grasa dura alrededor de los riñones y órganos que se consideraba selecta y sagrada. En las instrucciones sacrificiales de Levítico, el animal se divide en piezas incluyendo ''su cabeza, su sebo, sus piezas'', dispuestas sobre el altar. Esta grasa era la porción de Yahveh, prohibida para consumo humano y siempre quemada en sacrificio. El término aparece solamente en Levítico 1 y 8, describiendo la preparación apropiada de holocaustos. Aunque existe cierta incertidumbre sobre la raíz, el contexto indica claramente porciones de grasa interior selectas apartadas para Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6310', 'spa', 'Boca, filo, abertura, mandato; del órgano físico a sus extensiones (filo de espada, abertura de pozo, medida proporcional).', 'El sustantivo פֶּה designa primordialmente la boca física de seres humanos o animales, órgano del habla y la alimentación (395 apariciones). De esta raíz concreta surgen múltiples extensiones: el filo cortante de la espada en locuciones bélicas (''a filo de espada''), aberturas de recipientes y prendas (pozos, sacos, cuellos de vestidura), medidas proporcionales (''conforme a'' = según convenga) y pronunciamientos autoritativos que proceden de la boca (mandatos, decretos). El campo semántico abarca parte del cuerpo, apertura física, locución de medida y la metonimia boca-por-palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6311', 'spa', 'Aquí; de aquí — adverbio deíctico de referencia espacial que indica ubicación presente o punto de partida.', 'Aquí; de aquí — adverbio deíctico de referencia espacial que indica ubicación presente o punto de partida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6312', 'spa', 'Puá, Fuvá; nombre propio del padre de un juez y de un ancestro tribal de Isacar', 'Nombre propio que aparece en contextos genealógicos y judiciales. Génesis 46:13 y 1 Crónicas 7:1 enumeran a Puá (o Fuvá, con variante ortográfica) entre los hijos de Isacar, uno de los nietos de Jacob que fundaron una familia tribal. Números 26:23 se refiere al clan de los funitas descendientes de este Puá. Jueces 10:1 identifica al juez Tolá como hijo de Puá, aunque podría tratarse de un individuo diferente o referirse a ascendencia clásica. Las transliteraciones de la LXX varían, reflejando las variantes ortográficas del hebreo. El nombre posiblemente se relaciona con una raíz que denota plantas o brillo, pero su etimología sigue siendo incierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6313', 'spa', 'Entumecerse, desfallecer; perder vitalidad, quedar insensible o debilitado por conmoción o agotamiento', 'Verbo que describe el entumecimiento, el desfallecimiento o la pérdida de fuerzas, ya sea por conmoción emocional, dolor o agotamiento físico. En Génesis 45:26, el corazón de Jacob «se quedó entumecido» al escuchar que José vivía: no podía asimilar la noticia. Los Salmos lo emplean para expresar agotamiento tanto físico como espiritual: el salmista queda «entumecido» de tanto gemir (38:8) y su mano se adormece en la noche por la angustia (77:2). Habacuc lamenta que la justicia «se entumece», es decir, queda paralizada e ineficaz (1:4). El verbo describe la suspensión de funciones normales bajo una presión abrumadora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6314', 'spa', 'descanso, respiro, cese (especialmente alivio del sufrimiento o del llanto)', 'Sustantivo hebreo poco frecuente que aparece en Lamentaciones 2:18, en la frase ''no dé descanso la niña de tus ojos'' (es decir, no ceses de llorar). El término deriva de una raíz que significa ''entumecerse'' o ''volverse inactivo'', y aquí se refiere al cese o respiro de las lágrimas. El contexto es la destrucción de Jerusalén: el poeta exhorta a un llanto incesante por la devastación de la ciudad. La palabra captura la idea de detenerse, descansar o encontrar alivio de una acción o estado continuo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6315', 'spa', 'Respirar, soplar o bufar; del viento que sopla, palabras exhaladas, jadeo ansioso, avivar llama o desdén altivo', 'Construido sobre la imagen primordial del aliento que sale del cuerpo, este verbo se ramifica en usos sorprendentemente diversos. En el Cantar de los Cantares es la brisa literal que sopla sobre un jardín (4:16) o el fresco aliento del atardecer (2:17). Proverbios lo transforma en acto de habla: un testigo falso ''exhala'' mentiras (Pr 6:19; 14:5), mientras que uno fiel ''exhala'' verdad (Pr 12:17). Habacuc 2:3 lo aplica a una visión profética que ''jadea'' hacia su cumplimiento — no tardará. Una sola imagen raíz — el aliento expulsado — genera significados que van desde brisas suaves hasta resoplidos de desprecio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6316', 'spa', 'Put; pueblo y territorio en África, descendientes de Cam, frecuentemente mencionados como aliados militares de Egipto', 'Nombre propio Put (פּוּט), que designa un pueblo descendiente de Cam, generalmente identificado con una región del norte de África, posiblemente Libia o el territorio al oeste de Egipto. Put aparece en la Tabla de las Naciones como hijo de Cam junto a Cus, Mizraim y Canaán (Gn 10:6; 1 Cr 1:8). Los profetas lo mencionan consistentemente como aliado militar de Egipto: guerreros que servían como mercenarios o portadores de escudo (Jer 46:9; Ez 27:10; 30:5; 38:5; Nah 3:9). La tradición francesa lo traduce como Puth y Pul, reflejando una antigua confusión con el rey asirio Pul.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6317', 'spa', 'Putiel (nombre propio de persona, posiblemente de origen egipcio)', 'Nombre propio que aparece en Éxodo 6:25, identificando al suegro de Eleazar, hijo de Aarón. La hija de Putiel se casó con Eleazar, y de esa unión nació Finees, el sacerdote conocido por su celo. El nombre es inusual y podría reflejar influencia egipcia, lo cual encaja con el contexto del éxodo, dado que los israelitas habían vivido largo tiempo en Egipto. La etimología es incierta, aunque algunos sugieren que contiene el elemento ''Puti'' (posiblemente egipcio) combinado con el nombre divino ''El''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6319', 'spa', 'Potifera, sacerdote egipcio de On, suegro de José', 'Potifera era un sacerdote egipcio de On (Heliópolis) cuya hija Asenat se convirtió en esposa de José. El nombre, abreviado de Potifera (''aquel a quien Ra ha dado''), refleja patrones auténticos de nomenclatura egipcia y confirma la profunda integración de José en la sociedad egipcia. Faraón dio Asenat a José como parte de su elevación a segundo al mando. Su matrimonio produjo a Manasés y Efraín, haciendo de Potifera el abuelo de dos patriarcas tribales. Su estatus sacerdotal en el templo del dios sol en On indica una posición social elevada, subrayando el honor que Faraón otorgó a José.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6320', 'spa', 'Antimonio, cosmético ocular; polvo negro (kohl) usado para oscurecer y delinear los ojos', 'Sustancia cosmética, probablemente sulfuro de antimonio (kohl), empleada para maquillar los ojos oscureciéndolos y realzándolos. En 2 Reyes 9:30, Jezabel «se pintó los ojos» antes de su encuentro fatal con Jehú, sugiriendo embellecimiento o desafío. En 1 Crónicas 29:2 aparece entre los materiales preciosos que David reunió para el templo, posiblemente para trabajos de incrustación decorativa. Isaías 54:11 lo usa en la promesa divina de restaurar Jerusalén: «asentaré tus cimientos con antimonio», refiriéndose a piedras oscuras y preciosas. Jeremías 4:30 condena el embellecimiento con pintura ocular ante la destrucción inminente. El término abarca tanto el adorno personal como un mineral oscuro de gran valor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6322', 'spa', 'Pul; nombre de un rey asirio (Tiglat-piléser III) y posiblemente de un pueblo o región lejana', 'Nombre con doble referencia: principalmente, el rey asirio Tiglat-piléser III, quien invadió Israel durante el reinado de Manahem. En 2 Reyes 15:19 y 1 Crónicas 5:26 se menciona a «Pul, rey de Asiria», quien exigió tributo a Israel y posteriormente deportó a las tribus transjordanas. «Pul» era probablemente el nombre de trono o una designación alternativa utilizada por los escritores bíblicos para este monarca. Isaías 66:19 podría referirse a Pul como una nación lejana (junto a Tarsis, Lud y Tubal), aunque quizá se trate de un pueblo diferente. El nombre ilustra cómo los textos bíblicos a veces emplean distintos nombres para un mismo gobernante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6323', 'spa', 'estoy desamparado, estoy confundido (forma cohortativa en primera persona que expresa desesperación)', 'Forma verbal cohortativa en primera persona que aparece en el Salmo 88:15, expresando el estado de confusión, desamparo o agobio del salmista. El verbo deriva de una raíz de significado incierto, posiblemente relacionada con entumecerse, estar confundido o sentirse impotente. Algunos léxicos lo conectan con el rey asirio Pul (Tiglat-Piléser III), pero la lectura verbal se ajusta mejor al contexto del Salmo 88, un clamor de profunda angustia y abandono. El salmista describe un estado de total desorientación y debilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6324', 'spa', 'el punita (gentilicio del clan descendiente de Puá/Puvá, hijo de Isacar)', 'Adjetivo gentilicio hebreo que aparece en Números 26:23, designando al clan descendiente de Puá (o Puvá), hijo de Isacar. Los punitas fueron una de las familias contadas durante el segundo censo en el desierto, mientras Israel se preparaba para entrar en Canaán. Junto con Shiphrah, este término servía para organizar la estructura tribal, registrar las relaciones genealógicas y facilitar la distribución de la tierra prometida entre las tribus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6326', 'spa', 'Puá (nombre propio femenino de una partera hebrea en Egipto)', 'Nombre propio femenino que aparece en Éxodo 1:15, identificando a una de las dos parteras hebreas que desafiaron la orden del faraón de matar a los varones recién nacidos de Israel. Puá, junto con Sifrá, temió a Dios y preservó la vida de los niños, dando excusas al faraón. La valiente desobediencia civil de estas mujeres constituye un paso decisivo en la narrativa del éxodo, ya que sus acciones permitieron la supervivencia de la generación de Moisés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6327a', 'spa', 'Esparcir, dispersar o ser esparcido; de pueblos expulsados, ejércitos quebrantados o naciones diseminadas.', 'Esparcir, dispersar o ser esparcido; de pueblos expulsados, ejércitos quebrantados o naciones diseminadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6327b', 'spa', 'dispersador, esparcidor (el que dispersa o quebranta)', 'Participio hebreo que funciona como sustantivo, con el significado de ''dispersador'' o ''esparcidor'', que aparece en Nahúm 2:1 (TM 2:2). El término describe a un enemigo que avanza contra Nínive y que dispersará a los defensores de la ciudad. Algunos eruditos proponen enmendar el texto para leer ''martillo'' o ''maza'', enfatizando la violencia destructiva en lugar de la dispersión. La imagen encaja con la profecía de Nahúm sobre la caída violenta de Nínive: un atacante viene a quebrantar el poder aparentemente invencible de Asiria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6329', 'spa', 'Hifil: sacar, obtener, proveer; derramar sustento para otros; promover o hacer prosperar planes', 'Verbo usado exclusivamente en Hifil, centrado en la idea de sacar algo a la luz, ya sea favor, provisión o el avance de planes. En Proverbios aparece repetidamente como cuasi-sinónimo de מָצָא (''hallar''): quien halla sabiduría ''obtiene'' favor de YHWH (Pr 8:35; 18:22). El sentido de proveer aparece en Sal 144:13, donde los rebaños ''proveen'' millares, y en Is 58:10, donde uno ''derrama'' sustento para el hambriento. Un uso singular en Sal 140:8 invierte el sentido: ''no hagas prosperar sus designios'', revelando la acepción de hacer que algo tenga éxito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6330', 'spa', 'tropiezo, tambaleo o escrúpulo (de conciencia o estabilidad moral)', 'Sustantivo hebreo poco frecuente que aparece en 1 Samuel 25:31, describiendo un posible ''tropiezo'' o ''escrúpulo de conciencia'' que David evitaría si se abstenía de derramar sangre. Abigail advierte a David que matar a Nabal innecesariamente se convertiría en un tropiezo para él, ya sea como obstáculo moral o fuente de remordimiento al llegar a ser rey. El término deriva de una raíz que significa ''tambalearse'' y se refiere figuradamente a aquello que hace tropezar moral o emocionalmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6331', 'spa', 'romper, frustrar, anular, invalidar (pacto, plan o consejo)', 'Este verbo Hiphil significa destrozar planes, anular pactos o frustrar propósitos. Aparece en contextos de tratados rotos (Dios rompiendo el pacto con quienes rompen el Suyo), esquemas frustrados (Dios frustrando el consejo de las naciones) y acuerdos violados (quebrantar la fe). El verbo lleva peso legal y relacional—no meramente interrumpir sino anular formalmente lo que fue establecido. Dios es frecuentemente el sujeto, rompiendo pactos con los quebrantadores de pactos o frustrando los diseños de los impíos. El término implica disolución autoritativa de compromisos vinculantes o planes cuidadosamente trazados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6332', 'spa', 'Pur/Purim: suerte echada para determinar el destino; festividad que conmemora la liberación judía en Ester', 'Pur es un sustantivo que significa ''suerte'', probablemente tomado del acadio puru (piedra usada para echar suertes). En Ester 3:7, Amán echa el pur para determinar la fecha de su plan de destrucción contra los judíos, y el texto mismo explica que pur equivale a haggoral, ''la suerte''. La forma plural Purim se convirtió en el nombre de la festividad gozosa que celebra la reversión del complot de Amán (Est 9:26-32). El libro de Ester se esmera en explicar esta palabra extranjera a sus lectores hebreos, sugiriendo que el término no era nativo del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6334', 'spa', 'Porata (nombre propio persa, uno de los hijos de Amán)', 'Nombre propio de origen persa que aparece en Ester 9:8, identificando a uno de los diez hijos de Amán muertos por los judíos durante los eventos de Purim. Porata, junto con sus hermanos, fue ejecutado tras la reversión del complot de Amán contra los judíos. La Septuaginta muestra variantes ortográficas que reflejan la dificultad de transliterar nombres persas al hebreo y al griego. Su inclusión en la lista de los hijos de Amán subraya la derrota total del plan genocida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6335', 'spa', 'brincar, retozar, saltar con regocijo (verbo en segunda persona plural)', 'Forma verbal disputada que aparece en Jeremías 50:11, donde el profeta se burla de los destructores de Israel en Babilonia. El contexto evoca un brincar o retozar jubiloso, como becerros que saltan de alegría tras el saqueo de Israel. El verbo es raro y su significado exacto es incierto, pero transmite una celebración exuberante y quizás irreverente. Algunas versiones lo interpretan como ''habéis engordado'' en lugar de ''brincáis'', pero la imagen central es de vencedores festejando su conquista con abandono casi animal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6335a', 'spa', 'brincar, retozar, saltar, encabritarse (como becerros jóvenes)', 'Este verbo raro describe el salto exuberante o retozo, como becerros jugueteando en un pastizal. Jeremías lo usa para reprender a los guerreros de Babilonia que ''retozan como novilla'' en celebración arrogante. Habacuc lo aplica a caballos de caballería que ''se encabritan'' o ''se esparcen'' mientras cargan. Malaquías ofrece esperanza: los justos ''saltarán como becerros liberados del establo'' cuando salga el sol de justicia. El verbo captura movimiento sin restricción y gozoso—o, en el caso de Babilonia, celebración presuntuosa. Existen variantes textuales (diferencias ketiv/qere), pero el sentido de salto vigoroso permanece consistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6335b', 'spa', 'ser dispersado, esparcido (forma pasiva Nifal)', 'Verbo en perfecto Nifal que aparece en Nahúm 3:18, describiendo la dispersión del pueblo del rey asirio. El profeta anuncia al gobernante de Asiria que ''tu pueblo está esparcido por los montes'' sin nadie que lo reúna, imagen de desintegración y abandono total. La forma verbal es textualmente incierta; muchos eruditos sugieren leer una raíz más común para ''dispersar''. La imagen es de una población sin liderazgo, completamente dispersa, señal definitiva del colapso nacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6336', 'spa', 'el putita (designación gentilicia de Judá)', 'Designación gentilicia hebrea que aparece en 1 Crónicas 2:53, identificando un grupo familiar dentro de Judá. Los putitas eran uno de varios clanes descendientes de Quiriat-jearim, enumerados entre las subdivisiones de Judá. Como otras designaciones similares en las genealogías de Crónicas, este nombre preservaba la identidad de un grupo familiar judaíta, aunque la etimología del nombre y la historia específica de la familia son desconocidas. La Septuaginta presenta variaciones textuales al traducir este nombre de clan poco conocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6337', 'spa', 'Oro fino, oro puro refinado; término poético que expresa valor supremo y belleza en la literatura sapiencial y devocional.', 'Palabra distintivamente poética (פַּז) para designar el oro de la más alta pureza, usada exclusivamente en contextos literarios elevados. Aparece en paralelo con otros términos para el oro como זָהָב y כֶּתֶם, siempre intensificando el sentido de valor supremo. El salmista declara que las ordenanzas de Dios son más deseables que mucho oro fino (Sal 19:10), y el amado en el Cantar de los Cantares describe la cabeza de la amada como oro finísimo (Cnt 5:11). La Sabiduría personificada anuncia que su fruto supera al oro fino (Pr 8:19). El español distingue entre ''oro fino'' y ''oro puro'', intentando ambos captar la cualidad superlativa que פַּז transmite más allá del oro ordinario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6338', 'spa', 'refinado, purificado (participio Hofal que describe oro puro)', 'Participio Hofal que aparece en 1 Reyes 10:18, describiendo el ''oro refinado'' utilizado en el gran trono de Salomón. La forma verbal indica un proceso pasivo: el oro ha sido refinado o purificado, probablemente mediante fuego, para alcanzar una calidad superior. El término enfatiza el valor extraordinario y la maestría artesanal del trono. El pasaje paralelo en 2 Crónicas 9:17 emplea un término diferente (''puro''), y existe cierta incertidumbre léxica, pero el sentido es claro: se trata de oro de la más alta calidad, completamente purificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6340', 'spa', 'Esparcir o dispersar; se usa para Dios dispersando enemigos, huesos o escarcha, y para Israel disperso como oveja solitaria.', 'El verbo פָּזַר describe el acto enérgico de esparcir o dispersar personas, objetos o fenómenos naturales. En su forma activa Piel, aparece de modo notable con Dios como sujeto: Él esparce los huesos de los impíos (Sal 53:5), dispersa a sus enemigos como paja (Sal 89:10) y arroja escarcha sobre la tierra (Sal 147:16). Proverbios 11:24 lo aplica a la generosidad: quien «esparce» con liberalidad se enriquece aún más. Las formas pasivas pintan un cuadro más conmovedor: Jeremías llama a Israel «oveja dispersa» (Jer 50:17) y el Salmo 141:7 lamenta huesos esparcidos a la boca del Seol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6341a', 'spa', 'Trampa para aves, lazo — dispositivo de captura usado literal y figuradamente para tramas, calamidades y juicio.', 'Trampa para aves, lazo — dispositivo de captura usado literal y figuradamente para tramas, calamidades y juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6342', 'spa', 'Temer, estar aterrorizado, temblar de miedo; también reverencia; Hifil: causar temblor.', 'Temer, estar aterrorizado, temblar de miedo; también reverencia; Hifil: causar temblor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6343', 'spa', 'Pavor, terror, temor; una calamidad repentina; el objeto de temor o epíteto divino («el Temor de Isaac»)', 'Pavor, terror, temor; una calamidad repentina; el objeto de temor o epíteto divino («el Temor de Isaac»)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6345', 'spa', 'mi temor, mi pavor, reverencia hacia mí (con sufijo de primera persona)', 'Sustantivo hebreo con sufijo de primera persona que aparece en Jeremías 2:19, significando ''temor de mí'' o ''mi pavor''. Dios habla a través de Jeremías declarando que la apostasía y maldad de Israel los disciplinará, añadiendo ''no hay temor de mí en vosotros''. El término se refiere al temor reverente o asombro, la actitud religiosa apropiada hacia Dios que Israel ha abandonado. La construcción combina un sustantivo de ''pavor'' o ''reverencia'' con un sufijo de primera persona, enfatizando la relación personal que ha sido violada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6346', 'spa', 'Gobernador, prefecto provincial; administrador designado sobre un distrito, desde los períodos asirio hasta persa.', 'Gobernador, prefecto provincial; administrador designado sobre un distrito, desde los períodos asirio hasta persa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6347', 'spa', 'Gobernador; funcionario provincial designado bajo la autoridad imperial persa o babilónica.', 'Préstamo arameo procedente del acadio (y en última instancia del persa antiguo) que designa a un gobernador o administrador provincial nombrado por un poder imperial. En las secciones arameas de Esdras y Daniel, el término se refiere a funcionarios que gobernaban provincias en nombre del rey persa o babilónico. Aparece junto a otros rangos de la burocracia en Daniel 3:2–3, donde sátrapas, gobernadores y consejeros son convocados juntos. El vocablo refleja con precisión la estructura administrativa del imperio, y su uso en las listas de funcionarios subraya la jerarquía oficial del periodo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6349', 'spa', 'inestabilidad, desenfreno o licencia descontrolada (describiendo conducta impulsiva y sin restricción)', 'Sustantivo hebreo que aparece en Génesis 49:4, donde Jacob describe el carácter de Rubén en su oráculo de lecho de muerte. Jacob declara que Rubén es «inestable como el agua», utilizando este término para expresar desenfreno, temeridad y licencia desenfrenada. La palabra funciona como un abstracto por concreto, describiendo a alguien cuya conducta es tan incontrolable como agua hirviente o desbordada. Esta caracterización explica por qué Rubén, siendo el primogénito de Jacob, perdió los privilegios de la primogenitura a causa de su acto temerario de profanar la concubina de su padre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6350', 'spa', 'temeridad, jactancia presuntuosa (de los falsos profetas)', 'Sustantivo hebreo que aparece en Jeremías 23:32, donde Dios condena a los falsos profetas que extravían al pueblo «con su temeridad» o «jactancia». El término describe una conducta irresponsable y presuntuosa: profetas que hablan con atrevimiento sin haber recibido comisión divina. Relacionado con la raíz que denota desenfreno o conducta desmedida, este sustantivo capta la peligrosa combinación de confianza temeraria y falsa autoridad que caracteriza a los seudoprofetas que engañan al pueblo de Dios con mensajes no autorizados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6351', 'spa', 'atrapado, enredado en una trampa (infinitivo absoluto Hiphil que describe total cautividad)', 'Infinitivo absoluto Hiphil que aparece en Isaías 42:22, describiendo cómo Israel ha sido atrapado y enredado. La forma deriva de un verbo que significa «atrapar con lazo», y aquí describe al pueblo como «atrapado en hoyos» y «encerrado en calabozos». La forma gramatical del infinitivo absoluto enfatiza la totalidad e intensidad de la acción: están completamente atrapados. La imagen transmite la cautividad desamparada de Israel, capturado como animales en trampas sin que nadie venga a rescatarlos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6352', 'spa', 'carbón, brasas ardientes (para fuego o metalurgia)', 'Este término denota carbón o brasas ardientes, el combustible que sostiene el fuego. Proverbios lo usa en un proverbio sobre personas pendencieras: ''Como el carbón a las brasas y la leña al fuego, así es el hombre rencilloso para encender contienda''. Isaías lo menciona dos veces en contextos de metalurgia y juicio divino—el herrero trabaja sobre carbón, y Dios crea al herrero que sopla el fuego de carbón. La palabra enfatiza brasas resplandecientes que producen calor en lugar de mera ceniza. Algunos sugieren que Salmo 11:6 debería enmendarse para leer ''brasas de fuego'' en lugar de ''lazos''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6353', 'spa', 'alfarero (préstamo arameo para quien trabaja con arcilla)', 'Sustantivo arameo que aparece en Daniel 2:41, designando a un alfarero, es decir, quien trabaja con arcilla. La palabra es un préstamo lingüístico, probablemente del asirio, lo cual refleja el ambiente lingüístico de las porciones arameas de Daniel. En el sueño de Nabucodonosor, la estatua tiene pies en parte de hierro y en parte de «barro de alfarero», representando un reino dividido. El término sitúa el texto de Daniel en su contexto babilónico, donde el arameo era la lengua franca y el vocabulario cruzaba fronteras lingüísticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6354', 'spa', 'Fosa; hoyo en la tierra, usado literal y figuradamente para calamidad y entrampamiento.', 'Sustantivo masculino que significa fosa u hoyo cavado en la tierra. Aparece en contextos narrativos donde se arrojan cuerpos a una fosa (2 S 18:17) y donde los fugitivos se esconden en hoyos (2 S 17:9). Su uso más célebre se encuentra en la tríada aliterativa «terror, fosa y trampa» (pachad, pachat, pach) en Isaías 24:17–18 y Jeremías 48:43–44, donde la fosa representa el juicio divino ineludible. Lamentaciones 3:47 retoma la misma tríada. Las traducciones al español oscilan entre «hoyo», «fosa» y «cuevas», reflejando el rango que va desde la excavación literal hasta la perdición metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6355', 'spa', 'Pajat-Moab — nombre propio compuesto (''gobernador de Moab'') de un gran clan judío postexílico en las listas de retornados.', 'Pajat-Moab (פַּחַת מוֹאָב) es un nombre propio compuesto que significa «gobernador de Moab» y designa a un prominente clan judío postexílico o a su cabeza ancestral. El nombre probablemente conserva la memoria de un funcionario preexílico que sirvió como gobernador sobre Moab durante el período de influencia transjordana de Judá. El clan de Pajat-Moab fue uno de los grupos más numerosos en regresar de Babilonia: 2.812 miembros en el retorno de Zorobabel (Esd 2:6; Neh 7:11) y miembros adicionales bajo Esdras (Esd 8:4). Algunos de sus hombres estuvieron entre quienes se habían casado con mujeres extranjeras y accedieron a despedirlas (Esd 10:30). Hasub, hijo de Pajat-Moab, ayudó a reparar el muro de Jerusalén y la Torre de los Hornos (Neh 3:11), y el clan selló la renovación del pacto (Neh 10:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6356', 'spa', 'corrosión o deterioro que carcome el tejido; deterioro leproso en textiles', 'Este raro término hebreo aparece únicamente en las regulaciones sacerdotales sobre la lepra en tejidos (Levítico 13:55). Describe un proceso destructivo: una perforación o consumición del material que vuelve la prenda ritualmente impura. La palabra capta la naturaleza devoradora de la descomposición, como si algo estuviera activamente consumiendo las fibras. La evidencia multilingüe (corrosión, corroyendo) enfatiza el aspecto penetrante y destructivo, más allá de una simple contaminación superficial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6357', 'spa', 'Topacio; piedra preciosa amarilla o dorada, posiblemente crisólito, muy valorada en la antigüedad', 'Piedra preciosa tradicionalmente identificada como topacio (posiblemente crisólito o zafiro amarillo-dorado), de gran valor en el mundo bíblico. Éxodo 28:17 y 39:10 la sitúan como la segunda piedra en la primera fila del pectoral del sumo sacerdote, parte de las vestiduras sagradas que representaban a las tribus de Israel. Job compara el valor de la sabiduría con piedras preciosas, declarando que ni siquiera «el topacio de Cus» puede igualarla (28:19), siendo Cus famoso por sus gemas. Ezequiel incluye el topacio entre las piedras que adornaban al rey de Tiro en el Edén (28:13). Su color dorado y su rareza lo convertían en una gema apreciada para la ornamentación sagrada y real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6358', 'spa', 'Flores abiertas talladas; ornamentación floral esculpida en la madera del templo de Salomón', 'Término que designa flores abiertas o capullos tallados como elementos decorativos en la madera del interior del templo de Salomón. En 1 Reyes 6, los paneles de cedro del templo estaban tallados con calabazas y «flores abiertas» (versículos 18, 29, 32, 35), creando un patrón ornamental que evocaba un jardín paradisíaco. El interior del templo recordaba así al Edén mediante vegetación esculpida: no se veía piedra alguna, solo madera decorada con motivos botánicos. Las «flores abiertas» sugieren capullos en plena floración, representando vida, belleza y el florecimiento de la creación de Dios. Esta decoración transformaba el templo en un jardín sagrado donde cielo y tierra se encontraban.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6359', 'spa', 'Libres de obligaciones, exentos de deberes; los liberados de las tareas regulares del templo (variante Ketiv)', 'Esta forma aparece en 1 Cronicas 9:33 en la lectura Ketiv, describiendo a los cantores levitas que estaban exentos de otras tareas del templo. La raiz del termino implica separacion o liberacion, es decir, dejar libre a alguien de sus obligaciones habituales. Los cantores estaban apartados en un doble sentido: consagrados para su ministerio musical y, al mismo tiempo, liberados del trabajo rutinario que ocupaba a los demas levitas. El vocablo espanol ''libres'' capta bien este sentido de exencion y dedicacion exclusiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6360', 'spa', 'martillo, martillo de forja (usado por herreros)', 'Este término denota un martillo pesado, particularmente el martillo de forja usado por herreros. Isaías lo usa para el martillo del herrero que da forma al metal sobre el yunque. Jeremías lo emplea metafóricamente en dos imágenes poderosas: la palabra de Dios es como un martillo que quebranta la roca, y Babilonia misma fue ''el martillo de toda la tierra''—ahora roto. La palabra probablemente deriva o se conecta con el arameo, posiblemente describiendo la acción de golpear o la herramienta misma. Evoca poder, fuerza y el impacto transformador (o destructor) de golpes repetidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6362', 'spa', 'Separar, liberar, soltar, despedir; también escapar o escabullirse', 'Verbo cuyo significado nuclear de separación se ramifica en varias aplicaciones vívidas. David ''se escapó'' de la lanza de Saúl (1 S 19:10), ciertos levitas fueron ''liberados'' de otras tareas para dedicarse a la música (1 Cr 9:33), y Joiadá no ''despidió'' a las divisiones sacerdotales salientes durante el golpe contra Atalía (2 Cr 23:8). En Pr 17:14, quien ''suelta'' una contienda es como el que abre una brecha en un dique. El enigmático Sal 22:7 emplea el participio pasivo en un contexto de escarnio y rechazo. El español abarca desde ''libres'' hasta ''suelta'', mientras que el francés ''glissa au loin'' capta el matiz de fuga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6363a', 'spa', 'Lo que abre la matriz — el primogénito, sea humano o animal, consagrado al SEÑOR.', 'Este sustantivo aparece siempre en la frase constructa peter rechem («el que abre la matriz») y designa al hijo o animal primogénito que primero abre el vientre materno. El concepto es central en la ley israelita de consagración: por haber herido Dios a los primogénitos de Egipto, todo peter rechem en Israel —humano y animal por igual— pertenece al SEÑOR (Éx 13:2, 12-15). El término aparece en aposición con bekhor («primogénito») en Éxodo 13:2 y Números 3:12, mostrando que «el que abre la matriz» y «primogénito» son funcionalmente sinónimos, aunque peter enfatiza el acto físico del parto mientras que bekhor subraya el rango por orden de nacimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6363b', 'spa', 'Lo que abre; el primogenito como el que abre la matriz', 'Usado en forma constructa en Numeros 8:16, este termino designa al primogenito como ''el que abre la matriz''. Forma parte del fundamento teologico para la consagracion de los levitas: ellos sirven como sustitutos de todos los primogenitos de Israel, quienes pertenecian a Dios por ser los primeros en abrir el vientre de sus madres. El concepto vincula la primacia biologica con la obligacion pactal. Las traducciones multilingues preservan la imagen de apertura, enfatizando el acto de irrumpir e inaugurar la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6364', 'spa', 'Pi-beset: ciudad egipcia consagrada a la diosa Bastet, cerca de la moderna Zagazig', 'Este toponimo egipcio aparece en Ezequiel 30:17 dentro de un oraculo de juicio contra Egipto. El nombre de la ciudad deriva de Per-Bastet, ''Casa de Bastet'', en referencia a la diosa felina que alli se veneraba. Las fuentes griegas la conocian como Bubastis. Situada a unos 50 kilometros al noreste de El Cairo (actual Tell Basta, cerca de Zagazig), fue un importante centro religioso. Herodoto describe sus grandes festivales. Ezequiel profetiza que sus jovenes caeran a espada: los lugares sagrados de Egipto no ofreceran proteccion alguna ante el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6365', 'spa', 'ruina, desastre, calamidad, destrucción', 'Este sustantivo captura la ruina catastrófica o desastre, particularmente la calamidad repentina que sobreviene a una persona. Job lo usa tres veces para explorar respuestas a la desgracia ajena y su propio sufrimiento. Job 30:24 cuestiona si uno clama en su propia ruina. Job 31:29 protesta que nunca se alegró del desastre de su enemigo. Proverbios 24:22 advierte que la calamidad de parte de Dios y del rey surgirá repentinamente contra los rebeldes. El término enfatiza la naturaleza devastadora, a menudo inesperada, de la ruina—ya sea como juicio merecido o sufrimiento inmerecido que prueba el carácter moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6366', 'spa', 'Bordes o porciones de grasa de animales sacrificiales; trozos de sebo en las ofrendas', 'Este termino aparece en Jueces 3:16, aunque BDB lo conecta con una raiz distinta hallada en Levitico que describe porciones de grasa sacrificial. La palabra se refiere a los trozos o bordes de las partes grasas de los animales de sacrificio, particularmente el sebo que se quemaba como ofrenda. En el sistema levitico, ciertas porciones de grasa pertenecian a Dios y se consumian sobre el altar. La terminologia de ''bordes'' o ''piezas'' sugiere el proceso de cortar y disponer estas porciones selectas durante el ritual sacrificial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6367', 'spa', 'Pi-hahirot; lugar en la frontera oriental de Egipto donde Israel acampó antes de cruzar el mar Rojo', 'Nombre de lugar que señala el último campamento de Israel en territorio egipcio antes del cruce del mar Rojo. Éxodo 14:2 y 14:9 sitúan Pi-hahirot entre Migdol y el mar, frente a Baal-zefón, donde el ejército del faraón alcanzó a Israel. Números 33:7-8 registra las etapas del viaje: acampar en Pi-hahirot y partir de allí para cruzar el mar. El nombre posiblemente significa «boca de los canales» y se relaciona con las marismas de la frontera oriental de Egipto. Su ubicación exacta se desconoce, pero marcó el límite geográfico entre la esclavitud y la liberación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6369', 'spa', 'Ficol, comandante del ejército de Abimelec', 'Ficol fue el comandante militar que servía bajo Abimelec, rey de Gerar, durante la época de Abraham e Isaac. Aparece en momentos diplomáticos cruciales: acompañando a Abimelec cuando hace un pacto con Abraham en Beerseba (Génesis 21:22, 32), y nuevamente cuando Abimelec y Ahuzat se acercan a Isaac (Génesis 26:26). Su presencia constante como jefe militar de Abimelec sugiere un rol de consejero de confianza en las relaciones internacionales. El nombre parece ser no-semítico, posiblemente filisteo o egeo, encajando con el contexto filisteo de Gerar. Su papel subraya la seriedad de estas negociaciones de tratados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6370', 'spa', 'concubina — esposa secundaria de rango legal inferior, presente en hogares patriarcales, levíticos y reales', 'concubina — esposa secundaria de rango legal inferior, presente en hogares patriarcales, levíticos y reales');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6371', 'spa', 'Superabundancia de grasa; gordura corporal excesiva como metafora de complacencia', 'Aparece unicamente en Job 15:27, donde describe la acumulacion excesiva de grasa, no del tipo sacrificial, sino la abundancia repulsiva que habla de indulgencia y complacencia moral. Elifaz la usa para retratar al impio que ''cubrio su rostro con su gordura y acumulo grasa sobre sus lomos''. La imagen sugiere una prosperidad autosatisfecha que ciega a la realidad espiritual. Se trata de la gordura como condicion moral: la superabundancia que proviene de la autoindulgencia y no de la bendicion de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6372', 'spa', 'Finees — nieto de Aarón, celoso por la honra de Dios; también un hijo corrupto del sacerdote Elí.', 'Finees — nieto de Aarón, celoso por la honra de Dios; también un hijo corrupto del sacerdote Elí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6375', 'spa', 'Vacilación, temblor; el estremecimiento de las rodillas por terror o debilidad extrema', 'Este término vívido aparece en Nahúm 2:10 (o 2:11 en algunas versificaciones), dentro de una profecía sobre la caída de Nínive. La expresión «vacilación de rodillas» captura la manifestación física del terror: piernas que ya no pueden sostenerse firmes. Forma parte de una cascada de imágenes: corazones que se derriten, rodillas que chocan entre sí, angustia en todo el cuerpo y rostros pálidos. La palabra transmite ese temblor involuntario cuando el miedo se apodera del cuerpo hasta el punto de que funciones básicas como mantenerse en pie se vuelven imposibles. Los guerreros de Nínive, antes temibles, quedarían ellos mismos paralizados de espanto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6376', 'spa', 'Pisón: uno de los cuatro ríos que fluían desde el Edén en Génesis 2', 'El Pisón es nombrado como el primero de los cuatro ríos que se ramificaban del río que regaba el Edén (Génesis 2:11). Según el relato, serpenteaba por la tierra de Havila, donde se encontraban oro, bedelio y ónice. Su identificación geográfica sigue siendo incierta: las teorías van desde cursos de agua del Golfo Pérsico hasta ríos africanos o una geografía puramente simbólica. Lo que queda claro es que representaba abundancia y bendición, fluyendo desde el jardín de Dios hacia tierras ricas en recursos preciosos. El nombre mismo podría derivar de una raíz que significa «brotar» o «fluir», apropiado para un río que llevaba el agua vivificante del Edén al mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6378', 'spa', 'frasco, vasija pequeña o ampolla (especialmente para aceite)', 'Este término se refiere a un frasco pequeño o ampolla, particularmente para contener aceite de unción. Aparece en dos escenas pivotales de unción: Samuel ungiendo a Saúl como primer rey de Israel, y el siervo de Eliseo ungiendo a Jehú como rey sobre Israel. En ambos casos, el profeta toma ''un frasco de aceite'' y lo derrama sobre la cabeza del nuevo rey para consagrarlo. El tamaño pequeño del frasco se adecuaba a su propósito sagrado—conteniendo justo suficiente aceite precioso para el ritual. Este recipiente representa la selección y autorización divina, el medio físico por el cual la palabra profética se convierte en realidad efectuada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6379', 'spa', 'Goteo, fluir suavemente; agua que brota o mana de forma gradual', 'Este participio Piel aparece en Ezequiel 47:2, describiendo agua que brotaba desde el lado sur del umbral del templo en la visión del profeta. El término enfatiza un flujo suave y gradual, no un torrente sino un goteo constante. Este hilo de agua se convierte en el río de vida que crece en profundidad y anchura a medida que fluye hacia el oriente, trayendo finalmente sanidad al Mar Muerto. La elección de una palabra para fluir suavemente (en vez de brotar a borbotones) resalta la naturaleza milagrosa de la visión: incluso un simple goteo procedente de la presencia de Dios se transforma en un caudal que renueva la vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6380', 'spa', 'Poqueret-hazebaim; nombre ancestral que significa ''cazadora de gacelas'', cabeza de una familia postexílica', 'Nombre compuesto que significa «cazadora (o atrapadora) de gacelas», designando al cabeza de un grupo familiar postexílico. Aparece en las listas de descendientes de los siervos de Salomón que regresaron del exilio babilónico. Esdras 2:57 y Nehemías 7:59 registran a los «hijos de Poqueret-hazebaim» entre los sirvientes del templo que retornaron. El primer elemento del nombre es arameo con forma femenina que sugiere un oficio u ocupación, mientras que «hazebaim» significa «las gacelas». Esto podría indicar un oficio ancestral de caza o captura de gacelas, o bien una designación simbólica. La LXX ofrece transliteraciones variadas del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6381', 'spa', 'Ser extraordinario o sobrepasar; las maravillas de Dios; obrar prodigiosamente; demasiado difícil; hacer un voto especial', 'Ser extraordinario o sobrepasar; las maravillas de Dios; obrar prodigiosamente; demasiado difícil; hacer un voto especial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6382', 'spa', 'Prodigio, maravilla; algo extraordinario y sobrecogedor, especialmente los actos milagrosos de Dios', 'El sustantivo פֶּלֶא designa algo extraordinario que sobrepasa el entendimiento humano — un prodigio o maravilla, atribuido casi siempre a Dios. Junto al Mar Rojo, Moisés cantó que YHWH ''hacía maravillas'' (Éx 15:11). Los salmistas meditan sobre el פֶּלֶא de Dios tanto en la creación como en la redención (Sal 77:11, 14; 78:12; 88:10; 89:5). En Isaías 9:5, el niño mesiánico recibe el nombre de trono ''Consejero Admirable'' (פֶּלֶא יוֹעֵץ), donde la cualidad de prodigio pertenece a la figura real misma. Lamentaciones 1:9 usa el plural adverbialmente — Jerusalén ''descendió asombrosamente'' — expresando la naturaleza estremecedora e incomprensible de su caída.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6383', 'spa', 'maravilloso, incomprensible, más allá del entendimiento', 'Este adjetivo describe lo que trasciende la comprensión humana—lo maravilloso, lo misterioso, lo incomprensible. Aparece en dos contextos llamativos: la autodesignación del ángel en Jueces 13:18 (ketiv) y el asombro del salmista ante el conocimiento de Dios en Salmo 139:6. Cuando Manoa pregunta el nombre del ángel, él responde que es ''maravilloso''—demasiado extraordinario para ser pronunciado. El salmo declara que el conocimiento de Dios es ''demasiado maravilloso para mí, demasiado elevado para alcanzarlo''—reconociendo la vasta brecha entre el entendimiento humano y el divino. Existen variantes textuales (ketiv/qere), pero ambas apuntan al misterio trascendente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6384', 'spa', 'Los paluitas: descendientes de Palú, un clan dentro de la tribu de Rubén', 'Este adjetivo gentilicio aparece en Números 26:5 durante el censo de los clanes de Israel. Los paluitas eran descendientes de Palú, uno de los cuatro hijos de Rubén. Dado que Rubén fue el primogénito de Jacob, estos clanes trazaban su linaje hasta las primeras generaciones de Israel. El contexto del censo subraya la identidad tribal y los derechos de herencia: el recuento de cada clan era determinante para la distribución de tierras en Canaán. El uso del artículo definido («los paluitas») los presenta como una comunidad reconocida y definida dentro de la estructura tribal más amplia de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6385', 'spa', 'Dividir, separar; partir en secciones, abrir un canal o crear división entre partes', 'Verbo que significa dividir, partir o separar en partes. Génesis 10:25 y 1 Crónicas 1:19 explican el nombre de Péleg: «en sus días fue dividida la tierra», refiriéndose posiblemente a la división de lenguas en Babel o a la dispersión geográfica de los pueblos. Job 38:25 pregunta quién «abrió canal para la lluvia», describiendo el ordenamiento providencial de Dios sobre las tormentas. Salmo 55:9 pide a Dios que «divida sus lenguas», es decir, que confunda los planes de los enemigos, en posible alusión a Babel. El verbo abarca tanto la separación física (canales, tierra) como la división conceptual (lenguas, pueblos, planes).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6386', 'spa', 'Dividido, partido; estar fragmentado o separado en partes (arameo)', 'Este participio pasivo arameo aparece en Daniel 2:41, en la interpretación que Daniel hace del sueño de la estatua de Nabucodonosor. El reino dividido de hierro y barro representa un dominio internamente fragmentado: unido de nombre pero dividido en naturaleza, fuerte y a la vez frágil. El término captura la fractura política y social: un reino que no puede mantenerse cohesionado porque sus partes constitutivas no se adhieren entre sí. La imagen del hierro mezclado con barro que no logra unirse se convirtió en una poderosa metáfora a lo largo de la historia para imperios inestables que imponen unidad sobre elementos fundamentalmente incompatibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6387', 'spa', 'Mitad, porcion; la mitad de un todo (arameo)', 'Este sustantivo arameo aparece en Daniel 7:25, dentro de la formula profetica que describe la duracion de la persecucion del cuerno pequeno: ''un tiempo, tiempos, y medio tiempo.'' La ''mitad'' es esencial en esta expresion, pues indica un periodo incompleto, un tiempo truncado. Esta duracion quebrada transmite que, aunque la persecucion parezca interminable para quienes la sufren, Dios ha fijado limites definidos. El reino del mal no completara su curso; sera cortado. El medio tiempo lleva la secuencia a un final incompleto, subrayando la soberania divina sobre la opresion humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6388', 'spa', 'Arroyo, canal de agua; un curso de agua usado literal y figuradamente para la abundancia o las lágrimas.', 'Sustantivo poético que designa un arroyo, canal o acequia — una corriente de agua dividida (relacionado con la raíz p-l-g, ''dividir''). Los ''arroyos de agua'' junto a los cuales el justo está plantado (Sal 1:3) constituyen una de las imágenes más emblemáticas del Salterio. La palabra también describe lágrimas que corren como canales de agua (Lam 3:48, Sal 119:136) y canales de aceite que simbolizan prosperidad (Job 29:6). En el Salmo 65:9 el ''canal de Dios'' ofrece una vívida imagen de la lluvia como riego celestial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6389', 'spa', 'Peleg; nombre propio que significa ''división'', hijo de Eber, en cuyos días fue dividida la tierra', 'Nombre personal Peleg (פֶּלֶג), derivado de la raíz que significa ''dividir'', llevado por el hijo de Eber y padre de Reu en la línea genealógica de Sem a Abraham. Génesis explica el nombre etiológicamente: ''en sus días fue dividida la tierra'' (Gn 10:25), posiblemente en referencia a la dispersión de los pueblos tras Babel o a la división de tierras irrigadas. Las siete apariciones se dan en contextos genealógicos: la Tabla de las Naciones (Gn 10:25), el linaje de Sem a Abraham (Gn 11:16-19) y su repetición en Crónicas (1 Cr 1:19, 25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6390', 'spa', 'Arroyos, divisiones; corrientes de agua o subdivisiones de una tribu', 'Esta palabra aparece en Job 20:17 con clara referencia a arroyos de aceite y miel, representando la abundancia lujosa que los malvados jamas disfrutaran. La misma forma se encuentra en Jueces 5:15-16, donde puede significar ''arroyos'' o ''divisiones'' de Ruben, generando debate sobre si Debora critica a los rubenitas por quedarse junto a sus canales de agua o por permanecer divididos en facciones. La raiz porta ambos sentidos de agua fluyendo y de separacion, haciendo que el doble significado sea natural en hebreo. En el contexto de Job, la imagen de corrientes rebosantes de sustancias preciosas es inconfundible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6391', 'spa', 'divisiones, turnos (de sacerdotes o levitas para el servicio del templo)', 'Este término se refiere a las divisiones u órdenes organizadas de sacerdotes y levitas para el servicio rotativo del templo. Aparece en Jueces 5 en el cántico de Débora, describiendo divisiones tribales (quizás militares o sociales), y en 2 Crónicas 35 para las divisiones sacerdotales durante la Pascua de Josías. El sistema dividía a los sacerdotes en grupos (posteriormente formalizados como 24 turnos) que servían por rotación, asegurando tanto la continuidad del culto como la responsabilidad compartida. El término es paralelo a ''mahălōqet'', la palabra más común para divisiones. Esta estructura organizativa sostenía el servicio regular del templo mientras permitía que la mayoría de los sacerdotes vivieran en sus ciudades de origen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6392', 'spa', 'En sus divisiones; segun secciones organizativas o turnos de servicio (arameo)', 'Esta frase aramea aparece en Esdras 6:18, describiendo como los sacerdotes y levitas fueron organizados en sus divisiones para el servicio de la casa de Dios en Jerusalen. Tras el exilio, restablecer el culto del templo requeria organizar al clero en sus turnos tradicionales. El termino enfatiza un culto estructurado y ordenado, donde cada grupo conocia su momento y funcion. No se trataba de una asignacion arbitraria, sino de la restauracion del sistema davidico en el que las familias sacerdotales servian por rotacion, asegurando un servicio continuo y distribuyendo el honor y la responsabilidad entre todas las familias capacitadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6393', 'spa', 'Acero o guarniciones de hierro; piezas metalicas endurecidas en carros de guerra', 'Esta palabra poco frecuente aparece en Nahum 2:3, describiendo las guarniciones de acero o hierro de los carros de guerra que relampaguean como fuego mientras los atacantes de Ninive se preparan para la batalla. El termino designa metal endurecido, posiblemente acero, aunque esta tecnologia era limitada en el antiguo Cercano Oriente. Mas probablemente se refiere a hierro especialmente templado o revestimientos de hierro usados para reforzar carros de guerra o como adornos. Cuando estas superficies metalicas captaban la luz durante las maniobras militares, producian destellos igneos que anunciaban la aterradora aproximacion del ejercito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6394', 'spa', 'Pildas: hijo de Nacor y Milca, sobrino de Abraham', 'Pildas aparece en Genesis 22:22, dentro de la genealogia de Nacor, hermano de Abraham. Fue uno de los ocho hijos nacidos de Nacor y su esposa Milca, lo que lo convierte en sobrino de Abraham. Estas genealogias de los nacoritas establecen conexiones entre Israel y los pueblos arameos del norte de Mesopotamia. Aunque Pildas desaparece del relato biblico, su inclusion en esta lista familiar preserva la red de parentesco mas amplia de Abraham, relaciones que cobrarian importancia cuando Abraham envio a su siervo a buscar esposa para Isaac entre ''sus parientes'', y cuando Jacob huyo hacia Laban, otro descendiente de Nacor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6395', 'spa', 'Apartar, distinguir, separar (Hifil); ser hecho maravillosamente (Nifal); mostrar maravillas de modo prodigioso', 'Forma afín de la raíz más conocida פלא (''ser maravilloso''), esta raíz פלה se centra en la separación y distinción, pero con un matiz de asombro. Cuando Dios ''aparta'' la tierra de Gosén (Ex 8:22; 9:4), la distinción es en sí misma un prodigio. El Nifal en Salmo 139:14 (''fui hecho maravillosamente'') lleva la separación al terreno del asombro sagrado, donde el salmista se maravilla de haber sido formado de manera única e intrincada. El Hifil imperativo en Sal 17:7 pide a Dios que ''muestre maravillosamente'' su amor fiel, uniendo la idea de distinción con la de prodigio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6396', 'spa', 'Falú (Pallu), hijo de Rubén; ancestro de los faluitas, un clan rubenita', 'Nombre propio que posiblemente significa ''distinguido'' o ''separado'', llevado por el segundo hijo de Rubén, primogénito de Jacob. Falú aparece en las listas genealógicas que trazan a los descendientes de Rubén hasta Egipto (Gn 46:9), la genealogía sacerdotal (Éx 6:14), el censo y registro de clanes del desierto (Nm 26:5, 8) y el registro tribal del Cronista (1 Cr 5:3). Es el ancestro de Eliab y, a través de él, de Datán y Abiram, quienes luego se rebelaron contra Moisés. El español ''Falú'' refleja una tradición fonética alternativa, mientras que el francés, el inglés y el alemán usan consistentemente ''Pallu''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6397', 'spa', 'el pelonita, designación gentilicia de origen incierto', 'Esta designación gentilicia aparece en las listas de los valientes de David en Crónicas, pero casi con certeza es un error textual. 1 Crónicas 11:27 y 27:10 llaman a alguien ''el pelonita'', pero el pasaje paralelo en 2 Samuel 23:26 dice ''el paltita'' (de Bet-pelet). Similarmente, 1 Crónicas 11:36 tiene ''el pelonita'' donde 2 Samuel 23:34 dice ''el gilonita''. Los eruditos concuerdan ampliamente que son errores escribales, posiblemente por confusión entre letras hebreas similares (פ/ג) o nombres de lugares abreviados. La designación no representa un lugar o clan real sino más bien una corrupción textual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6398', 'spa', 'Hender, partir, traspasar; en Piel, abrir o cortar a través, rebanar', 'Verbo que denota la acción enérgica de hender o partir. En su forma Qal describe el arar o partir la tierra (Sal 141:7), mientras que el Piel intensifica la imagen hacia el traspaso de órganos (Job 16:13; Pr 7:23) o el corte de productos dentro de una olla (2 R 4:39). El español ''atraviesa'' y ''dan a luz'' captan el espectro desde la penetración violenta hasta la apertura del vientre en el parto (Job 39:3). La raíz comparte cognados con palabras árabes y arameas que significan hender y labrar la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6399', 'spa', 'Servir o rendir culto a una deidad; verbo arameo para la devoción religiosa y el servicio reverente.', 'Verbo arameo que significa servir, adorar o rendir reverencia a una deidad, cognado del acadio palahu (''temer, reverenciar''). Aparece exclusivamente en las porciones arameas de Daniel y Esdras. Es el término central en las escenas de confrontación de Daniel: Sadrac, Mesac y Abed-nego se niegan a servir a los dioses de Nabucodonosor (Dn 3:12–18), y Daniel continúa sirviendo a su Dios a pesar del decreto (Dn 6:17, 21). En Esdras 7:24 la forma participial funciona como sustantivo: ''servidores de la casa de Dios''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6400', 'spa', 'Rodaja, tajada o sección; usado para piedras de molino y porciones cortadas de fruta (granada, torta de higos)', 'Designa una porción cortada o hendida de algo, abarcando dos referentes distintos en la Biblia hebrea: piedras de molino y rodajas de fruta. Como término de molienda, pelach designa la piedra superior o inferior de un molino de mano (Jue 9:53; 2 Sam 11:21; Job 41:24), evocando pesadez y dureza. Como término frutal, describe una rodaja de granada usada como símil para la sien de la amada en el Cantar de los Cantares (4:3; 6:7) y una tajada de torta de higos dada al egipcio hambriento en 1 Samuel 30:12. La imagen subyacente es siempre algo partido o hendido de un todo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6401', 'spa', 'Pilha: líder israelita postexílico que selló el pacto de Nehemías', 'Pilha fue uno de los líderes que sellaron el pacto en Nehemías 10:24, comprometiéndose junto con el pueblo a la observancia de la Torá tras el exilio. Esta ceremonia de sellado siguió a la lectura pública de la Ley por parte de Esdras y a la confesión de pecados del pueblo. Los firmantes representaban a la dirigencia comunitaria: sacerdotes, levitas y cabezas de familia que asumían la responsabilidad corporativa por la fidelidad de Israel. La firma de Pilha lo situó entre este círculo de reformadores postexílicos decididos a evitar los errores que habían conducido al destierro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6402', 'spa', 'Para el servicio; para el culto o ministerio litúrgico (arameo)', 'Esta frase aramea aparece en Esdras 7:19, dentro del decreto del rey persa que autorizaba a Esdras a llevar los utensilios del templo de vuelta a Jerusalén «para el servicio de la casa de tu Dios». El término abarca tanto la adoración como el ministerio práctico: todo lo necesario para el funcionamiento del templo. Resulta notable que un funcionario persa empleara este lenguaje, reconociendo que estos utensilios no eran simples objetos valiosos sino implementos sagrados con propósito religioso. La frase refleja la naturaleza funcional de la adoración: el servicio (avodá) involucra tanto actos litúrgicos como el trabajo práctico de mantener la casa de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6403', 'spa', 'Escapar, librar, rescatar; como participio: libertador; Hifil: arrebatar; raramente, dar a luz (parto).', 'Escapar, librar, rescatar; como participio: libertador; Hifil: arrebatar; raramente, dar a luz (parto).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6407', 'spa', 'El paltita: gentilicio procedente de Bet-pelet en Judá', 'Este adjetivo gentilicio aparece en 2 Samuel 23:26 para identificar a Helez, uno de los valientes de David, como «el paltita». La designación lo vincula a Bet-pelet, una localidad en el sur de Judá. La fuerza de élite de David reclutaba guerreros de todas las tribus y regiones de Israel, y estos identificadores geográficos preservan sus orígenes. El pasaje paralelo en 1 Crónicas 11:27 confirma esta conexión. Para estos guerreros, el gentilicio de su pueblo natal se integraba en su identidad: no era solo «Helez» sino «Helez el paltita», asociando para siempre el valor personal con las raíces locales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6408', 'spa', 'Piltai: cabeza de familia sacerdotal durante el sumo sacerdocio de Joiaquim', 'Piltai aparece en Nehemías 12:17 como cabeza de una familia sacerdotal durante el tiempo del sumo sacerdote Joiaquim, en las generaciones posteriores al regreso de Babilonia. Las listas de Nehemías 12 trazan la continuidad de las familias sacerdotales, demostrando que a pesar de la disrupción del exilio, el sacerdocio legítimo sobrevivió y fue reconstituido en Jerusalén. Piltai representa un eslabón en esta cadena de ministerio autorizado. La cuidadosa preservación de estos nombres refleja la seriedad con que el judaísmo postexílico trataba las cuestiones de linaje y autorización para el servicio sagrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6410', 'spa', 'Pelatías — nombre propio que significa ''Yah ha librado'', llevado por varios personajes del AT', 'Nombre teofórico compuesto de la raíz p-l-t (librar, rescatar) con el sufijo divino -yahu/-yah, que significa ''Yahvé ha librado''. Lo llevan al menos tres individuos: un príncipe del pueblo cuya muerte repentina Ezequiel presenció en una visión (Ez 11:1, 13), un nieto de Zorobabel en la línea davídica (1 Cr 3:21) y un capitán simeonita (1 Cr 4:42). El nombre también aparece entre los firmantes del pacto de Nehemías (Neh 10:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6411b', 'spa', 'Pelaías: descendiente de David en el período postexílico', 'Pelaías aparece en 1 Crónicas 3:24 dentro de la genealogía de la línea real de David, varias generaciones después del exilio. Aunque el trono davídico ya no existía en términos políticos, estas genealogías preservaban el linaje real, manteniendo viva la esperanza en las promesas del pacto de Dios con David. Cada nombre representaba continuidad: la línea de la promesa no se había extinguido. Para los judíos postexílicos, conocer quién descendía de David importaba tanto para cuestiones legales inmediatas como para la esperanza escatológica de que algún día un hijo de David restauraría el reino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6412a', 'spa', 'Fugitivo, prófugo; sobreviviente, remanente — quien ha huido del peligro o quien queda con vida tras una catástrofe. El sustantivo פָּלִיט designa a u', 'Fugitivo, prófugo; sobreviviente, remanente — quien ha huido del peligro o quien queda con vida tras una catástrofe. El sustantivo פָּלִיט designa a una persona que ha escapado o sobrevivido a un desastre, ya sea derrota militar, juicio divino o catástrofe nacional. En su uso principal enfatiza el acto de huir: un fugitivo que se escabulle del enemigo, como aquel que ''escapó y vino a avisar a Abram'' sobre la captura de Lot (Gn 14:13). Pero la palabra también se desliza hacia el sentido de quien ha sobrevivido, un remanente que perdura, como en las repetidas referencias de Ezequiel a quienes sobrevivirán a la espada y recordarán al SEÑOR entre las naciones (Ez 6:8-9; 7:16). La distinción entre huir y sobrevivir es sutil pero real, confirmada por las glosas multilingües que alternan entre ''fugitivo'' y ''sobreviviente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6412b', 'spa', 'fugitivos, escapados; los que han sobrevivido a la destruccion o al exilio', 'Plural de un adjetivo-sustantivo derivado de la raiz p-l-t (escapar), que designa a quienes han huido o sobrevivido a una catastrofe. En Numeros 21:29 describe a los hijos de Moab entregados como fugitivos a Quemos. Los textos profeticos lo aplican a los sobrevivientes de la caida de Babilonia que llevan noticias de vuelta a Sion (Jer 50:28; 51:50) y al remanente de Juda que huyo a Egipto (Jer 44:14). Isaias 66:19 presenta a estos escapados como emisarios enviados a naciones lejanas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6413', 'spa', 'Escape o liberación del peligro; el remanente sobreviviente de personas o cosas que escaparon de la destrucción.', 'Escape o liberación del peligro; el remanente sobreviviente de personas o cosas que escaparon de la destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6414', 'spa', 'jueces, árbitros, los que deciden casos', 'Este término denota jueces o árbitros legales que emiten decisiones en disputas. Aparece tres veces, cada una planteando cuestiones interpretativas. Éxodo 21:22 probablemente se refiere a jueces que evalúan las penas en un caso de lesión a una mujer embarazada. Deuteronomio 32:31 dice ''siendo nuestros enemigos los jueces''—incluso los adversarios de Israel deben reconocer la superioridad de Yahvé. Job 31:11 lo usa en paralelo con ''iniquidad'', describiendo el adulterio como ''una iniquidad para los jueces''—un crimen que requiere castigo judicial. El término enfatiza el rol judicial—aquellos autorizados para sopesar evidencia, emitir veredictos e imponer penas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6415', 'spa', 'Decisión, arbitraje; acto de emitir juicio o ejercer mediación judicial', 'Este término aparece en Isaías 16:3, donde se insta a Moab a «dar decisión» o «actuar como juez» en favor de los refugiados de Judá que huyen de la opresión. La palabra se refiere al oficio de árbitro o mediador: aquel que evalúa los casos y pronuncia un fallo justo. Isaías contempla a Moab brindando protección judicial y tomando decisiones rectas a favor de los vulnerables. El término subraya el aspecto activo y funcional de la justicia: no meramente ocupar un cargo judicial, sino ejercer de hecho el discernimiento, sopesar la evidencia y dictar veredictos que amparen al inocente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6416', 'spa', 'Para los jueces; que requiere atención judicial, delito que exige juicio legal', 'Este adjetivo aparece en Job 31:28, donde Job declara que ciertos pecados serían «iniquidad para los jueces», es decir, delitos que exigen atención y castigo judicial. En su juramento de inocencia, Job enumera pecados secretos que podrían escapar a la vista humana y luego señala aquellos que serían públicamente enjuiciables si se descubrieran. La idolatría cae en esta segunda categoría: no solo una traición personal contra Dios, sino un crimen contra la comunidad que requiere juicio legal. La expresión indica ofensas que caen bajo la jurisdicción de los tribunales terrenales, violaciones tan graves que demandan intervención judicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6417', 'spa', 'Juicio, emisión de decisiones; función judicial o profética de determinar casos', 'Este término aparece en Isaías 28:7, en la denuncia de Isaías contra sacerdotes y profetas que «titubean en el juicio» a causa de la embriaguez. La palabra se refiere al ejercicio activo de emitir decisiones, ya sean veredictos judiciales u oráculos proféticos. Tanto sacerdotes como profetas desempeñaban funciones de discernimiento: los sacerdotes enseñaban la Torá y resolvían casos rituales, los profetas transmitían la palabra de Dios para guiar a la nación. Cuando estos líderes estaban ebrios, su juicio —su capacidad de percibir con rectitud y decidir con sabiduría— quedaba comprometido. El término captura ese momento crítico en que se debe tomar una determinación y un liderazgo incompetente fracasa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6418', 'spa', 'Huso (para hilar) o distrito administrativo; dos sentidos genuinamente distintos en un mismo sustantivo.', 'El sustantivo פֶּלֶךְ presenta uno de los casos más llamativos de polisemia en hebreo: la misma palabra designa tanto un huso para hilar como un distrito administrativo. La conexión puede residir en la idea de ''girar'' o ''circundar'' — un huso gira, y un distrito es un circuito delimitado de territorio. En 2 Samuel 3:29, David maldice a la casa de Joab con hombres que ''sostienen el huso'', insinuando debilidad, mientras que Proverbios 31:19 elogia a la mujer virtuosa cuyas manos agarran el פֶּלֶךְ. El sentido administrativo predomina en Nehemías 3, donde se nombran ocho distritos distintos de la Jerusalén postexílica en el relato de la reconstrucción de la muralla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6419', 'spa', 'Orar, interceder o mediar; principalmente en Hitpael, dirigir súplica hacia Dios; en Piel, juzgar o intervenir.', 'Orar, interceder o mediar; principalmente en Hitpael, dirigir súplica hacia Dios; en Piel, juzgar o intervenir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6420', 'spa', 'Palal: constructor que ayudó a reparar las fortificaciones de Jerusalén bajo Nehemías', 'Palal se menciona en Nehemías 3:25 como uno de los individuos que trabajaron en la reconstrucción de la muralla de Jerusalén. El nombre en sí está relacionado con la oración o la intercesión, algo muy apropiado para alguien dedicado a la obra sagrada de restaurar la ciudad de Dios. Cada constructor nombrado en Nehemías 3 representa tanto una edificación literal como una reconstrucción espiritual. No se limitaban a apilar piedras, sino que reconstituían Jerusalén como ciudad santa, una declaración física de que el pueblo de Dios había regresado y no sería removido. La sección particular de Palal incluía reparaciones cerca de la torre saliente y la casa alta del rey.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6421', 'spa', 'Pelalías: sacerdote, hijo de Amsi, en la Jerusalén postexílica', 'Pelalías aparece en Nehemías 11:12 como un sacerdote que servía en la Jerusalén postexílica, identificado específicamente como hijo de Amsi. El nombre significa algo así como «Yahvé ha intervenido» o «Yahvé ha juzgado», una carga teológica muy significativa para un sacerdote cuya función consistía en mediar la intervención divina a través del sacrificio y la bendición. Estas genealogías sacerdotales en Nehemías documentan la legítima restauración del servicio del templo después del exilio. Pelalías representa a una de las familias que mantenían la línea sacerdotal autorizada, asegurando que el culto en el templo restaurado fuera llevado a cabo por descendientes debidamente acreditados de Aarón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6422', 'spa', 'A cierto uno; a alguien no especificado o sin nombre (pronombre arameo)', 'Esta frase aramea aparece en Daniel 8:13, donde un ser santo habla «a cierto uno», alguien no identificado. Es una vaguedad deliberada, como decir «a alguien» o «a fulano». El texto no identifica ni al que habla ni al destinatario, manteniendo un aura de misterio en torno a la conversación angélica que Daniel alcanza a escuchar. Esta indefinición cumple un propósito literario: Daniel está presenciando un diálogo celestial que no estaba originalmente dirigido a él, captando solo fragmentos de una discusión mayor sobre las blasfemias del cuerno pequeño y la profanación del santuario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6423', 'spa', 'fulano, cierto individuo (designación indefinida para persona o lugar no nombrado)', 'Este pronombre sirve como marcador indefinido—''fulano'' o ''cierto individuo''—cuando se evita o retiene un nombre específico. Siempre se empareja con ''almonî (otro término indefinido) en la expresión ''pelonî almonî'', que significa ''fulano de tal persona/lugar''. Rut 4:1 tiene a Boaz dirigiéndose al pariente más cercano como ''Ven aquí, amigo, y siéntate''—literalmente ''fulano de tal''. 1 Samuel 21:3 y 2 Reyes 6:8 lo usan para lugares no nombrados: ''tal y tal lugar''. La construcción es paralela al árabe ''fulān'' y al moderno ''Juan Pérez''—una no-identificación deliberada, ya sea por privacidad, anonimato o efecto retórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6424', 'spa', 'Pesar, ponderar, evaluar; nivelar o allanar un camino (Piel denominativo de peles, ''balanza'')', 'Verbo Piel denominativo derivado del sustantivo que significa ''balanza'', palas evoca la imagen vívida de colocar algo en una balanza para comprobar su verdadero peso. En una línea de uso, describe pesar o ponderar acciones y carácter, como cuando el salmista acusa a los jueces corruptos de ''pesar violencia'' (Sal 58:2). En la otra, significa nivelar y allanar un camino, ya sea Dios nivelando la senda del justo (Isa 26:7) o el sabio exhortando al discípulo a enderezar el sendero bajo sus pies (Prov 4:26). Los sentidos de ''pesar'' y ''allanar'' captan con precisión estas dos facetas de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6426', 'spa', 'Temblar, estremecerse; sacudirse violentamente ante una perturbación cósmica', 'Este verbo en Hitpael aparece en Job 9:6, describiendo cómo los pilares de la tierra se estremecen cuando Dios sacude el mundo en su ira. Se trata de un temblor violento e involuntario, el tipo de estremecimiento que provoca una perturbación de escala cósmica. La imagen es la de los cimientos mismos de la creación respondiendo al poder divino con sacudidas convulsivas. Job emplea esta metáfora para ilustrar el poder abrumador de Dios: si hasta los pilares que sostienen el mundo tiemblan ante su toque, ¿cómo puede un ser humano pretender enfrentarlo en un litigio? El término captura el terror existencial a escala cósmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6427', 'spa', 'Estremecimiento, horror; temblor de pavor o espanto que se apodera del cuerpo ante el terror', 'Sustantivo abstracto que designa la reacción física de estremecerse o temblar por horror y pavor. Job describe cómo al recordar su aflicción tiembla y «el estremecimiento se apodera de mi carne» (21:6). El salmista clama que «temor y temblor vienen sobre mí, y el horror me envuelve» al contemplar la violencia de sus enemigos (55:5). Isaías retrata la noche de placer convertida en estremecimiento: el terror reemplaza al gozo (21:4). Ezequiel advierte que «el espanto cubrirá todos los rostros» cuando llegue el juicio (7:18). El término captura el terror visceral: la reacción corporal involuntaria ante un miedo abrumador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6428', 'spa', 'revolcarse (en polvo o ceniza) como rito de duelo; sumirse en el lamento', 'Verbo en Hitpael que describe la accion de revolcarse en polvo o ceniza como expresion de duelo intenso o lamentacion. Los profetas ordenan este rito funebre: Jeremias exhorta a la hija de su pueblo a revolcarse en ceniza (Jer 6:26) y manda a los pastores del rebano hacer lo mismo (Jer 25:34). Ezequiel retrata a los marineros de Tiro arrojando polvo sobre si y revolcandose en ceniza por la angustia (Ez 27:30). Miqueas 1:10 lo emplea en un juego de palabras con la ciudad de Bet-le-afra (''casa de polvo'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6429', 'spa', 'Filistea (פְּלֶשֶׁת) — territorio costero de los filisteos en el suroeste de Canaán, usado en textos poéticos y tardíos.', 'פְּלֶשֶׁת es el nombre geográfico hebreo para Filistea, la franja costera del suroeste de Canaán habitada por los filisteos. Esta forma particular aparece exclusivamente en textos poéticos y tardíos, nunca en las narraciones en prosa de Jueces o Samuel donde los filisteos tienen un papel tan destacado. Surge por primera vez en el Cántico del Mar (Éx 15:14), luego en oráculos proféticos contra las naciones (Is 14:29, 31) y en varios salmos (Sal 60:10 = 108:10; 83:8; 87:4). La tradición griega lo traduce como allophyloi (''extranjeros'') en vez de transliterarlo, reflejando cómo la LXX percibía a los filisteos como forasteros por excelencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6430', 'spa', 'Filisteo(s) — el pueblo de la llanura costera de Canaán, o un individuo de esa nación.', 'Adjetivo gentilicio que designa a los filisteos, los Pueblos del Mar que se asentaron en la llanura costera meridional de Canaán. En su forma plural (פְּלִשְׁתִּים), aparece más de 250 veces como denominación nacional colectiva — el rival persistente de Israel desde Jueces hasta el reinado de David. El singular con artículo (הַפְּלִשְׁתִּי) se refiere casi exclusivamente a Goliat, el campeón de Gat a quien David venció (1 S 17). Las traducciones multilingües reflejan tanto la transliteración (español ''filisteos'', alemán ''Philister'') como la traducción interpretativa (griego ἀλλόφυλοι, ''extranjeros''), revelando cómo los traductores antiguos ya percibían a este pueblo como forasteros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6431', 'spa', 'Pelet, nombre de dos hombres (probable variante textual en Números)', 'Este nombre aparece en dos contextos. En Números 16:1, ''Pelet'' se lista como padre de On el rubenita, uno de los participantes en la rebelión de Coré—pero la mayoría de los eruditos considera esto un error textual por ''Falú'' (פַּלּוּא), un nombre de clan rubenita conocido. On hijo de Pelet desaparece de la narrativa inmediatamente, nunca mencionado en las secuelas de la rebelión, apoyando la teoría de corrupción. En 1 Crónicas 2:33, Pelet aparece como descendiente de Judá. El nombre probablemente significa ''liberación'' si es genuino, pero en Números probablemente es una corrupción escribal que accidentalmente creó una figura fantasma en las genealogías de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6432', 'spa', 'Peleteos; cuerpo de soldados de élite en la guardia real de David, siempre emparejados con los cereteos.', 'Sustantivo gentilicio הַפְּלֵתִי que designa a los peleteos, una de las dos mitades de la guardia personal de élite de David, mencionados siempre junto a los cereteos (הַכְּרֵתִי). Su origen étnico es debatido: posiblemente mercenarios filisteos o egeos que se unieron a David durante sus años en Filistea. Aparecen en cada crisis del reinado de David: custodiando el trono (2 Sam 8:18; 20:23), siguiendo al rey al exilio durante la revuelta de Absalón (2 Sam 15:18), persiguiendo la rebelión de Seba (2 Sam 20:7) y escoltando a Salomón a su coronación (1 Re 1:38, 44). Su lealtad inquebrantable los convierte en pieza clave del aparato militar davídico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6433', 'spa', 'Boca (arameo); el órgano del habla o la abertura de algo, usado en Daniel para reyes, bestias y un foso', 'Equivalente arameo del hebreo peh (''boca''), que aparece seis veces en Daniel. Se refiere a la boca física de un rey que promulga un decreto (Dan 4:31), a la boca de los leones en el foso (Dan 6:22), a la boca de una bestia apocalíptica que devora (Dan 7:5) y a la boca del cuerno pequeño que habla con arrogancia (Dan 7:8, 20), así como a la abertura de un foso sellado con una piedra (Dan 6:17). El término conlleva peso tanto literal como figurado: habla, consumo y contención fluyen de esta única palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6434', 'spa', 'Las esquinas; puntos angulares o extremos de estructuras o territorios', 'Esta forma plural aparece en Zacarías 14:10 describiendo la extensión geográfica de la Jerusalén elevada en la visión escatológica. Las «esquinas» se refieren a puntos angulares o extremos, los vértices de la ciudad que definen sus límites. En contextos arquitectónicos bíblicos, las esquinas marcan puntos estructurales críticos donde los muros se encuentran y la resistencia se concentra. En la descripción territorial, las esquinas delimitan la extensión del terreno. El uso de Zacarías sugiere totalidad: de una esquina a otra abarca el conjunto, toda Jerusalén transformada y elevada, desde la Puerta de Benjamín hasta el sitio de la puerta anterior, hasta la Puerta de la Esquina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6435', 'spa', 'No sea que — conjunción que introduce una cláusula de propósito negativo o aprensión, expresando temor de un resultado indeseado.', 'פֶּן es una conjunción que aparece 133 veces, siempre introduciendo una cláusula que expresa algo que el hablante teme o desea prevenir: ''no sea que muráis'' (Gn 3:3), ''no sea que nos dispersemos'' (Gn 11:4), ''no sea que extienda su mano'' (Gn 3:22). Sigue regularmente a imperativos, advertencias o declaraciones de precaución — ''guárdate no sea que olvides'' (Dt 4:9; 6:12; 8:11). Su fuerza es consistentemente de evitación ansiosa o previsión protectora. Su etimología es debatida: algunos la conectan con פָּנָה (''volverse'') como ''para el apartamiento de'', mientras otros la relacionan con una partícula aramea que significa ''quizá''.');